use std::collections::{HashMap, HashSet};

/// A* shortest path from `start` to `goal`, guided by `heuristic`. Returns the node path
/// (inclusive of both ends) or `None` if `goal` is unreachable.
pub fn a_star(
    adj: &HashMap<String, Vec<(String, u32)>>,
    start: &str,
    goal: &str,
    heuristic: impl Fn(&str) -> u32,
) -> Option<Vec<String>> {
    let mut g_score: HashMap<String, u32> = HashMap::from([(start.to_string(), 0)]);
    let mut came_from: HashMap<String, String> = HashMap::new();
    let mut open: HashSet<String> = HashSet::from([start.to_string()]);
    while !open.is_empty() {
        let current = open
            .iter()
            .min_by_key(|n| {
                g_score.get(*n).copied().unwrap_or(u32::MAX).saturating_add(heuristic(n))
            })
            .cloned()
            .unwrap();
        if current == goal {
            let mut path = vec![current.clone()];
            let mut step = current;
            while let Some(prev) = came_from.get(&step) {
                path.push(prev.clone());
                step = prev.clone();
            }
            path.reverse();
            return Some(path);
        }
        open.remove(&current);
        let g_current = g_score.get(&current).copied().unwrap_or(u32::MAX);
        if let Some(neighbors) = adj.get(&current) {
            for (next, w) in neighbors {
                let tentative = g_current.saturating_add(*w);
                if tentative < g_score.get(next).copied().unwrap_or(u32::MAX) {
                    came_from.insert(next.clone(), current.clone());
                    g_score.insert(next.clone(), tentative);
                    open.insert(next.clone());
                }
            }
        }
    }
    None
}

use std::collections::{HashMap, HashSet, VecDeque};

/// Breadth-first traversal order from `start` over an adjacency map.
pub fn bfs(adj: &HashMap<&str, Vec<&str>>, start: &str) -> Vec<String> {
    let mut order = Vec::new();
    let mut seen = HashSet::from([start]);
    let mut queue = VecDeque::from([start]);
    while let Some(node) = queue.pop_front() {
        order.push(node.to_string());
        for &next in adj.get(node).into_iter().flatten() {
            if seen.insert(next) {
                queue.push_back(next);
            }
        }
    }
    order
}

/// Binary search a sorted slice; `Some(index)` on a hit, else `None`.
pub fn binary_search<T: Ord>(xs: &[T], target: &T) -> Option<usize> {
    let (mut lo, mut hi) = (0, xs.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match xs[mid].cmp(target) {
            std::cmp::Ordering::Equal => return Some(mid),
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
        }
    }
    None
}

// Pure style atoms for the cloud-blueprint column (`list/CloudBlueprints.tsx`, #3802) — the spinner
// rotation (keyframe `bim-spin`, `styles/blueprintImport.css`) + the shared loading shimmer (#2234).
