    for (let i = 1; i < a.length; i++) {
      let j = i;
      a.cursor("i", i);
      while (j > 0) {
        a.cursor("j", j);
        if (a.compare(j - 1, j) <= 0) break;
        a.swap(j - 1, j);
        j--;
      }
    }
    a.markSorted();
  },
})

