import type { ArrayFrame } from "@bsc/algorithms/trace";

/** Insertion sort as a step-yielding generator (generator-as-source, #3171): mutates `a` in place and
 *  yields one ArrayFrame per step. The plain `sort` drains it to order the array; the Algorithms
 *  Visualization pane animates the same yields - compare/swap verbs bound to <ArrayView>'s animations. */
export function* sortSteps(a: number[]): Generator<ArrayFrame> {
  yield { structure: "array", data: [...a] };
  for (let i = 1; i < a.length; i++) {
    let j = i;
    while (j > 0) {
      yield { structure: "array", data: [...a], ops: [{ op: "compare", at: [j - 1, j] }], cursors: { i, j } };
      if (a[j - 1] <= a[j]) break;
      [a[j - 1], a[j]] = [a[j], a[j - 1]];
      yield { structure: "array", data: [...a], ops: [{ op: "swap", at: [j - 1, j] }], cursors: { i, j } };
      j--;
    }
  }
  yield { structure: "array", data: [...a], ops: a.map((_, k) => ({ op: "mark", at: k, as: "sorted" })) };
}

/** Sort ascending by draining the generator (one source of truth). Pure - never mutates the input. */
export const sort = (input: number[]): number[] => {
  const a = [...input];
  const steps = sortSteps(a);
  while (!steps.next().done) { /* drain - sortSteps mutates `a` in place */ }
  return a;
};

/**
 * Merge K differently-shaped event streams into ONE recent-first feed, with a distinguished class
 * pinned ABOVE the time sort, plus a count per kind.
 *
 * The shape behind every "activity" / "what needs attention" panel that draws from several sources at
 * once (errors, warnings, denials, …). Three things it gets right that the hand-written version gets
 * wrong under maintenance:
 *
 * 1. **Heterogeneous in, homogeneous out.** Each stream has its OWN shape and its own projection to a
 *    common item; the merge never sees the source shapes. Adding a stream is adding a `(source,
 *    project)` pair, not editing a growing sort.
 * 2. **A pinned class outranks recency.** Some items are LIVE ("this is happening now") and must sit
 *    at the top regardless of timestamp — a currently-stalled worker above yesterday's resolved error.
 *    Modelled as a real flag (`pinned`), not the sentinel `sortKey: Infinity` the original used, which
 *    silently breaks the moment a second pinned item needs ordering among its peers.
 * 3. **Counts come from the merged feed, not recomputed.** One pass, so the badge can never disagree
 *    with the list it summarises.
 *
 * Sort is STABLE within a rank: pinned-vs-unpinned first, then `sortKey` descending, ties keeping
 * input order — so equal-timestamp items don't reshuffle between renders. Harvested from the Fleet
 * page's health panel (#3462/#3465).
 */

/** One normalized feed entry. `kind` is the caller's classification (counted); `pinned` lifts it above
 *  the time sort; `sortKey` orders the rest (a timestamp, descending = newest first). */
export interface FeedItem<TKind extends string> {
  kind: TKind;
  pinned: boolean;
  sortKey: number;
}

/** One input stream: its raw items plus how to project each to a {@link FeedItem}. Generic over the
 *  source shape AND the extra payload `P` the projection carries through (label, detail, …). */
export interface FeedStream<TKind extends string, P> {
  items: readonly unknown[];
  project: (raw: unknown) => (FeedItem<TKind> & P) | null;
}

/** Build one typed stream — a small helper so the source type is inferred rather than cast at the
 *  call site (each stream keeps its own element type until `project` normalizes it). */
export function feedStream<TRaw, TKind extends string, P>(
  items: readonly TRaw[],
  project: (raw: TRaw) => (FeedItem<TKind> & P) | null,
): FeedStream<TKind, P> {
  return { items, project: (raw) => project(raw as TRaw) };
}

/** The merged result: the ordered feed and a count per kind (every kind in `kinds` present, zeros
 *  included, so a caller can render a fixed set of badges without guarding for missing keys). */
export interface MergedFeed<TKind extends string, P> {
  items: Array<FeedItem<TKind> & P>;
  counts: Record<TKind, number>;
  total: number;
  hasItems: boolean;
}

/**
 * Merge the streams into one ordered feed with per-kind counts.
 *
 * `kinds` is the closed set of classifications, passed IN so `counts` has a zero for every one — the
 * feed alone can only count kinds that occurred, and a badge row that appears and disappears with the
 * data is worse than one that reads `0`.
 *
 * A stream's `project` returning null drops that raw item (a "done" verdict is not an error), so
 * filtering is part of the projection rather than a separate pass the caller has to remember.
 */
export function mergeFeeds<TKind extends string, P>(
  streams: ReadonlyArray<FeedStream<TKind, P>>,
  kinds: readonly TKind[],
): MergedFeed<TKind, P> {
  const items: Array<FeedItem<TKind> & P> = [];
  for (const stream of streams) {
    for (const raw of stream.items) {
      const item = stream.project(raw);
      if (item) items.push(item);
    }
  }
  // Stable: pinned first, then newest first, ties keeping insertion order (Array.sort is stable).
  items.sort((a, b) => (a.pinned === b.pinned ? b.sortKey - a.sortKey : a.pinned ? -1 : 1));

  const counts = Object.fromEntries(kinds.map((k) => [k, 0])) as Record<TKind, number>;
  for (const it of items) counts[it.kind] += 1;

  return { items, counts, total: items.length, hasItems: items.length > 0 };
}

use std::collections::{HashMap, VecDeque};

/// Kahn's algorithm — a topological ordering of a DAG, or `None` if a cycle is present.
pub fn topological_sort(adj: &HashMap<String, Vec<(String, u32)>>) -> Option<Vec<String>> {
    let mut indegree: HashMap<String, usize> = HashMap::new();
    for (node, edges) in adj {
        indegree.entry(node.clone()).or_insert(0);
        for (next, _) in edges {
            *indegree.entry(next.clone()).or_insert(0) += 1;
        }
    }
    let mut queue: VecDeque<String> = indegree
        .iter()
        .filter(|(_, &d)| d == 0)
        .map(|(n, _)| n.clone())
        .collect();
    let mut order = Vec::new();
    while let Some(node) = queue.pop_front() {
        order.push(node.clone());
        if let Some(edges) = adj.get(&node) {
            for (next, _) in edges {
                let d = indegree.get_mut(next).unwrap();
                *d -= 1;
                if *d == 0 {
                    queue.push_back(next.clone());
                }
            }
        }
    }
    if order.len() == indegree.len() {
        Some(order)
    } else {
        None
    }
}

export function transpose(m: number[][]): number[][] {
  const a = m.map((r) => [...r]);
  const n = a.length;
  for (let i = 0; i < n; i++)
    for (let j = i + 1; j < n; j++) [a[i][j], a[j][i]] = [a[j][i], a[i][j]];
  return a;
}

// useCtxRequired (#1775, extracted from Planning.tsx) — the dynamic Context required-set
// (#1019/#1028): polled from plan.db, baseline-seeded once per project/session. The Context gate
// reads it; context files gate on GENERATION (the file exists), not confirmation, so there's
// nothing to confirm/mirror. Returns the live required-topic list.
import { useState, useEffect, useRef } from "react";
import { usePoll } from "@/shared/hooks/usePoll";
import { bscJson, bscRun } from "@/shared/lib/core/bsc";
import { DISCOVERY_BASELINE } from "@/features/planner/stages/planStageDerive";
import type { BlueprintStage } from "@/features/planner/stages/blueprints";

export function useCtxRequired(effectiveProjectId: string, planSecs: BlueprintStage[]): string[] {
  const [ctxRequired, setCtxRequired] = useState<string[]>([]);
  const ctxRequiredJsonRef = useRef<string>("");
  const ctxSeededRef = useRef<Set<string>>(new Set());

  // #1019: clear the cached manifest on a project switch so a stale set never bleeds across.
  useEffect(() => { setCtxRequired([]); ctxRequiredJsonRef.current = ""; }, [effectiveProjectId]);

  // #1028: poll the Context required-set from plan.db and seed the baseline once per project. The
  // gate reads it to check each required topic's `context/<topic>.md` exists.
  usePoll((isCancelled) => {
    if (!effectiveProjectId) return;
    const tick = async () => {
      try {
        // `bsc plan discovery list --json` emits the required-topic string array (the same `Vec<String>`
        // the old `plan_list_discovery` command returned); bscJson degrades to [] when plan.db is absent.
        const m = await bscJson<string[]>(effectiveProjectId, ["plan", "discovery", "list", "--json"], []);
        if (isCancelled()) return;
        // Seed the baseline once per project/session if the set is empty — a deterministic floor before
        // the planner runs `bsc-plan context require`. The blueprint's context section `requires`
        // overrides the universal baseline (blueprint seeding).
        if ((m?.length ?? 0) === 0 && !ctxSeededRef.current.has(effectiveProjectId)) {
          ctxSeededRef.current.add(effectiveProjectId);
          const requires = planSecs.find(s => s.key === "discovery")?.requires ?? DISCOVERY_BASELINE;
          for (const t of requires) {
            await bscRun(effectiveProjectId, ["plan", "discovery", "require", t]);
          }
          return; // next tick reads the seeded set
        }
        const j = JSON.stringify(m ?? []);
        if (j !== ctxRequiredJsonRef.current) {
          ctxRequiredJsonRef.current = j;
          setCtxRequired(m ?? []);
        }
      } catch { /* plan.db not created until the planner/seed touches context — ignore */ }
    };
    return tick();
  }, 2000, [effectiveProjectId, planSecs]);

  return ctxRequired;
}

// Fleet GitHub-derived analytics (#415): throughput, merge queue, time-to-land,
// aggregated across the fleet's repos via the ETag-cached githubRequest. Pure
// mapping is in lib/fleetGithub; this is the fetch orchestration.
import { useState, useEffect } from "react";
import { githubRequest, isGithubAuthError } from "@/shared/lib/github/github";
import { useAppStore } from "@/store";
import {
  mapThroughput, mapMergeQueue, mapTimeToLand, deriveThroughputKpis,
  type ThroughputSlice, type MergeQueueRow, type FleetThroughputKpis,
  type GhIssueItem, type GhStatusState,
} from "@/shared/lib/github/fleetGithub";
import type { GhPull } from "@/shared/lib/github/repoPulseLive";

const WINDOW_DAYS = 14;
/** Cap on open PRs we fetch a CI status for (one call each). */
const STATUS_CAP = 12;

/** A PR with the head sha we need for the combined-status call. */
interface GhPullFull extends GhPull { head: { ref: string; sha: string } }

export interface FleetGithub {
  throughput: ThroughputSlice;
  mergeQueue: MergeQueueRow[];
  timeToLand: Array<{ label: string; v: number }>;
  medianLandH: number;
  kpis: FleetThroughputKpis;
  loading: boolean;
  error: string | null;
  /** how many repos were aggregated. */
  repoCount: number;
}

const EMPTY: FleetGithub = {
  throughput: { labels: [], landed: [], merged: [] },
  mergeQueue: [], timeToLand: [], medianLandH: 0,
  kpis: { landedToday: 0, prsMergedWeek: 0, avgLandH: 0 },
  loading: false, error: null, repoCount: 0,
};

export function useFleetGithub(repos: string[], refreshNonce = 0): FleetGithub {
  const githubToken = useAppStore(s => s.githubToken);
  const [data, setData] = useState<FleetGithub>(EMPTY);
  const key = repos.join(",");

  useEffect(() => {
    if (!githubToken || repos.length === 0) { setData(EMPTY); return; }
    let cancelled = false;
    setData(d => ({ ...d, loading: true, error: null }));

    (async () => {
      try {
        const since = new Date(Date.now() - WINDOW_DAYS * 86_400_000).toISOString();
        const get = <T,>(path: string, fallback: T): Promise<T> =>
          githubRequest<T>(path).catch((e) => { if (isGithubAuthError(e)) throw e; return fallback; });

        // Pulls (all states) + recently-closed issues, per repo.
        const perRepo = await Promise.all(repos.map(async slug => {
          const [pulls, issues] = await Promise.all([
            get<GhPullFull[]>(`repos/${slug}/pulls?state=all&per_page=100&sort=updated&direction=desc`, []),
            get<GhIssueItem[]>(`repos/${slug}/issues?state=closed&per_page=100&since=${since}`, []),
          ]);
          return { slug, pulls, issues };
        }));
        if (cancelled) return;

        const allPulls: GhPull[] = perRepo.flatMap(r => r.pulls);
        const allIssues: GhIssueItem[] = perRepo.flatMap(r => r.issues);

        // Open PRs → fetch combined CI status for the head sha (bounded).
        const open = perRepo.flatMap(r => r.pulls.filter(p => p.state === "open").map(p => ({ pr: p, repo: r.slug })));
        const capped = open.slice(0, STATUS_CAP);
        const statuses = await Promise.all(capped.map(({ pr, repo }) =>
          get<{ state: GhStatusState }>(`repos/${repo}/commits/${pr.head.sha}/status`, { state: null as unknown as GhStatusState })
            .then(s => ({ pr, repo, status: s?.state ?? null }))));
        if (cancelled) return;

        const now = new Date();
        const throughput = mapThroughput(allPulls, allIssues, WINDOW_DAYS, now);
        const live: FleetGithub = {
          throughput,
          mergeQueue: mapMergeQueue(statuses),
          timeToLand: mapTimeToLand(allPulls),
          medianLandH: deriveThroughputKpis(throughput, allPulls, now).avgLandH,
          kpis: deriveThroughputKpis(throughput, allPulls, now),
          loading: false, error: null, repoCount: repos.length,
        };
        if (!cancelled) setData(live);
      } catch (e) {
        if (cancelled) return;
        setData({ ...EMPTY, error: isGithubAuthError(e) ? "GitHub authorization failed — reconnect in Settings." : "Couldn't load fleet activity from GitHub." });
      }
    })();

    return () => { cancelled = true; };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, githubToken, refreshNonce]);

  return data;
}

// Live Fleet view model (#412). Reads the running fleet from the store
// (`fleetPaneStreams` roster + live `paneStatus`) and polls the coordination log
// (`read_coord_log` → `ingestCoordLog`) for blocked/asking/waiting, then assembles
// the worker roster via the pure mappers in lib/fleetLive.
import { useMemo } from "react";
import { useAppStore } from "@/store";
import { useCoordLog } from "@/shared/lib/fleet/useCoordLog";
import { buildLiveWorkers, deriveFleetKpis, statusCounts, type LiveWorker, type FleetKpis } from "@/shared/lib/fleet/fleetLive";

export interface UseFleetLive {
  workers: LiveWorker[];
  kpis: FleetKpis;
  counts: Partial<Record<LiveWorker["status"], number>>;
  hasFleet: boolean;
}

export function useFleetLive(): UseFleetLive {
  const fleetPaneStreams = useAppStore(s => s.fleetPaneStreams);
  const paneStatus       = useAppStore(s => s.paneStatus);
  const tabs             = useAppStore(s => s.tabs);
  const disabledPanes    = useAppStore(s => s.disabledPanes);
  const profiles         = useAppStore(s => s.agentProfiles);

  // The coordination log is the fleet's own activity feed (blocked/asking/waiting,
  // landed/merged). Polled while the screen is mounted — no store wiring needed.
  const { state: coord } = useCoordLog({ limit: 1000 });

  const workers = useMemo(
    () => buildLiveWorkers({ fleetPaneStreams, paneStatus, coord, tabs, disabledPanes, profiles }),
    [fleetPaneStreams, paneStatus, coord, tabs, disabledPanes, profiles],
  );
  const kpis = useMemo(() => deriveFleetKpis(workers), [workers]);
  const counts = useMemo(() => statusCounts(workers), [workers]);

  return { workers, kpis, counts, hasFleet: workers.length > 0 };
}

// Data hook for the GitHub summary dashboard (#1644).
//
// Owns the fetch lifecycle (events + contribution calendar + per-repo PRs/languages/
// runs/contributors for the N most-recently-updated repos) and exposes the memoized
// derivations every card renders from. All the React-free shaping lives in
// `lib/githubSummary.ts`; this hook only wires fetch → state → derived view models.

import { useState, useEffect, useMemo } from "react";
import { useAppStore } from "@/store";
import { timeAgo } from "@/shared/lib/core/format";
import { githubRequest, githubGraphql } from "@/shared/lib/github/github";
import { languageStats } from "@/features/github/languageStats";
import type { GHEvent } from "@/shared/lib/github/types";
import {
  SUMMARY_REPO_SAMPLE,
  CONTRIB_QUERY,
  buildHeatmap,
  countMergedPRs,
  buildCrossRepoEvents,
  buildOpenPRs,
  buildContributors,
  buildCiMatrix,
  buildRepoGrid,
  ciPassingPercent,
  type GHPRItem,
  type GHRunItem,
  type GHContrib,
  type RepoData,
  type ContribDay,
} from "@/features/github/lib/githubSummary";

/** Raw fetched state, before the per-card derivations. */
function useGitHubSummaryData() {
  const { githubToken, githubUser, githubRepos } = useAppStore();
  const [loading, setLoading] = useState(false);
  const [events, setEvents] = useState<GHEvent[]>([]);
  const [repoData, setRepoData] = useState<Record<string, RepoData>>({});
  const [contribDays, setContribDays] = useState<ContribDay[]>([]);

  const slugKey = githubRepos.slice(0, SUMMARY_REPO_SAMPLE).map(r => r.full_name).join(",");

  useEffect(() => {
    if (!githubToken || !githubUser) return;
    const login = githubUser.login;
    const slugs = githubRepos.slice(0, SUMMARY_REPO_SAMPLE).map(r => r.full_name);
    if (slugs.length === 0 && !login) return;

    setLoading(true);

    const eventsP = githubRequest<GHEvent[]>(`users/${login}/events?per_page=100`).catch((): GHEvent[] => []);

    const contribP = githubGraphql<{
      viewer: { contributionsCollection: { contributionCalendar: { weeks: Array<{ contributionDays: Array<{ contributionCount: number; date: string; weekday: number }> }> } } }
    }>(CONTRIB_QUERY, null).then(d => {
      const weeks = d?.viewer?.contributionsCollection?.contributionCalendar?.weeks ?? [];
      const days: ContribDay[] = [];
      weeks.forEach(w => w.contributionDays.forEach(cd => days.push({ date: cd.date, weekday: cd.weekday, count: cd.contributionCount })));
      return days;
    }).catch((): ContribDay[] => []);

    const repoPs = slugs.map(slug =>
      Promise.all([
        githubRequest<GHPRItem[]>(`repos/${slug}/pulls?state=open&per_page=20`).catch((): GHPRItem[] => []),
        githubRequest<Record<string, number>>(`repos/${slug}/languages`).catch((): Record<string, number> => ({})),
        githubRequest<{ workflow_runs: GHRunItem[] }>(`repos/${slug}/actions/runs?per_page=30`)
          .catch(() => ({ workflow_runs: [] as GHRunItem[] })),
        githubRequest<unknown>(`repos/${slug}/stats/contributors`)
          .then(d => Array.isArray(d) ? d as GHContrib[] : []).catch((): GHContrib[] => []),
      ])
    );

    Promise.all([eventsP, contribP, ...repoPs]).then(([evts, days, ...rows]) => {
      const evtArr = Array.isArray(evts) ? evts : [];
      const rd: Record<string, RepoData> = {};
      slugs.forEach((slug, i) => {
        const [prs, langs, runsResp, contribs] = rows[i] as [
          GHPRItem[],
          Record<string, number>,
          { workflow_runs: GHRunItem[] },
          GHContrib[],
        ];
        rd[slug] = {
          prs: Array.isArray(prs) ? prs : [],
          langBytes: langs && typeof langs === "object" && !Array.isArray(langs) ? langs : {},
          runs: Array.isArray(runsResp?.workflow_runs) ? runsResp.workflow_runs : [],
          contribs: Array.isArray(contribs) ? contribs : [],
        };
      });
      setEvents(evtArr);
      setContribDays(Array.isArray(days) ? days : []);
      setRepoData(rd);
      setLoading(false);
    }).catch(() => setLoading(false));
  }, [githubToken, githubUser?.login, slugKey]); // eslint-disable-line react-hooks/exhaustive-deps

  return { loading, events, repoData, contribDays };
}

/**
 * The summary's full view model: the fetch state plus every per-card derivation
 * (heatmap, contributors, open PRs, CI matrix, repo grid, language mix, KPIs).
 */
export function useGithubSummary() {
  const githubRepos = useAppStore(s => s.githubRepos);
  const { loading, events, repoData, contribDays } = useGitHubSummaryData();

  const heatmap = useMemo(() => buildHeatmap(contribDays), [contribDays]);
  const totalMerged = useMemo(() => countMergedPRs(events), [events]);
  const crossRepoEvts = useMemo(() => buildCrossRepoEvents(events), [events]);
  const openPRs = useMemo(() => buildOpenPRs(repoData, timeAgo), [repoData]);
  const { totals: langTotals, repoCount: langRepoCount } = useMemo(() => languageStats(repoData), [repoData]);
  const contributors = useMemo(() => buildContributors(repoData), [repoData]);
  const ciMatrix = useMemo(() => buildCiMatrix(githubRepos, repoData), [githubRepos, repoData]);
  const repoGridData = useMemo(() => buildRepoGrid(githubRepos, repoData, events), [githubRepos, repoData, events]);

  // KPIs
  const kpiOpenPRs = Object.values(repoData).reduce((s, rd) => s + rd.prs.length, 0);
  const kpiContribs = contributors.length || "—";
  const kpiCIPassing = ciPassingPercent(githubRepos, repoData);

  return {
    loading,
    githubRepos,
    heatmap,
    totalMerged,
    crossRepoEvts,
    openPRs,
    langTotals,
    langRepoCount,
    contributors,
    ciMatrix,
    repoGridData,
    kpiOpenPRs,
    kpiContribs,
    kpiCIPassing,
  };
}

// The MCP screen's install/version machinery (#885) lifted out of the screen: the per-server
// status map keyed by NAME, the version check on page open (mcp_check_update for each installed
// downloadable server), and the download (catalog) / update (installed) flows that drive it. Only
// downloadable first-party servers have this; built-in/remote servers carry no status.

import { useState, useEffect } from "react";
import { invoke } from "@tauri-apps/api/core";
import { catalogLink, repoNameFromLink, mcpRepoName } from "@/features/mcp/lib/mcpInstall";
import { type McpStat, type McpCheckResult, deriveCheckStat, installedDownloadableNames } from "@/features/mcp/lib/mcpVersioning";
import type { McpServer } from "@/features/mcp/lib/mcpServers";
import type { CatalogItem } from "@/shared/data/mcpCatalog";

export interface UseMcpInstallStatus {
  /** Per-server install/version status (#885), keyed by server NAME. */
  mcpStatus: Record<string, McpStat>;
  /** One-click install (#885): clone → `onCloned` (add to Installed silently) → build. */
  downloadFromCatalog(item: CatalogItem, onCloned: (item: CatalogItem) => void): Promise<void>;
  /** Update (or finish building) an installed downloadable server (#885): pull then rebuild. */
  updateInstalled(server: McpServer): Promise<void>;
}

export function useMcpInstallStatus(mcpServers: McpServer[]): UseMcpInstallStatus {
  // Keyed by server NAME. Refreshed on page open via mcp_check_update; advanced by the download
  // (catalog) and update (installed) actions.
  const [mcpStatus, setMcpStatus] = useState<Record<string, McpStat>>({});
  const setStat = (name: string, s: McpStat) => setMcpStatus(m => ({ ...m, [name]: s }));

  // Version check on every page open (#885): for each installed downloadable server, ask the
  // backend whether its clone is behind its remote (and whether it's built). Best-effort + async;
  // an in-flight download/update is left alone.
  useEffect(() => {
    const servers = installedDownloadableNames(mcpServers);
    if (servers.length === 0) return;
    let cancelled = false;
    for (const name of servers) {
      setMcpStatus(m => (m[name] ? m : { ...m, [name]: "checking" }));
      invoke<McpCheckResult>("mcp_check_update", { name: mcpRepoName(name) })
        .then(r => {
          if (cancelled) return;
          const next = deriveCheckStat(r);
          setMcpStatus(m => (m[name] === "downloading" || m[name] === "building" || m[name] === "updating" ? m : { ...m, [name]: next }));
        })
        .catch(() => {});
    }
    return () => { cancelled = true; };
    // Re-check when the set of installed downloadable servers changes (and on mount).
  }, [installedDownloadableNames(mcpServers).join(",")]); // eslint-disable-line react-hooks/exhaustive-deps

  /** One-click install (#885): clone → add to Installed silently (`onCloned`) → build. */
  async function downloadFromCatalog(item: CatalogItem, onCloned: (item: CatalogItem) => void) {
    if (!item.link) return;
    const repo = repoNameFromLink(item.link);
    setStat(item.name, "downloading");
    try {
      await invoke<string>("mcp_clone", { name: repo, url: item.link });
    } catch {
      setStat(item.name, "error");
      return;
    }
    onCloned(item);
    setStat(item.name, "building");
    try {
      const r = await invoke<{ ok: boolean }>("mcp_build", { name: repo });
      setStat(item.name, r.ok ? "current" : "needs-build");
    } catch {
      setStat(item.name, "needs-build");
    }
  }

  /** Update (or finish building) an installed downloadable server (#885): pull then rebuild. */
  async function updateInstalled(e: McpServer) {
    const link = catalogLink(e.name);
    if (!link) return;
    const repo = repoNameFromLink(link);
    setStat(e.name, "updating");
    try {
      await invoke("mcp_clone", { name: repo, url: link });
      setStat(e.name, "building");
      const r = await invoke<{ ok: boolean }>("mcp_build", { name: repo });
      setStat(e.name, r.ok ? "current" : "needs-build");
    } catch {
      setStat(e.name, "error");
    }
  }

  return { mcpStatus, downloadFromCatalog, updateInstalled };
}

// usePlanGates (#1474) — the planner's gate/`signals` derivation, extracted verbatim from
// Planning.tsx. Owns the live `stageState` snapshot, the lint/injection gates, the skip/confirm
// signal bags, the flat `signals` bag the declarative section gates read, and the focused-pane
// derivations (`stages`, active index, current-gate-ready, plan-complete, status label).
//
// Pure derivation, no side effects. `planSecs` (the blueprint sections) and the focused-pane
// SELECTION state (`focusSel`/`focusSelectedIdx`/`focusSelStage`) STAY in Planning and are passed
// in / read off this hook's outputs — only the auto-derived `stages`/`focusActiveIdx` move here.

import { useMemo } from "react";
import type { Section } from "@/features/planner/github/ghStructure";
import type { BlueprintStage } from "@/features/planner/stages/blueprints";
import { skippedSignal, confirmedSignal, planStagesComplete } from "@/features/planner/stages/blueprints";
import { derivePlanStageState, planStateToSignals } from "@/features/planner/stages/planStageDerive";
import { FEATURES_KEY } from "@/features/planner/stages/planTopics";
import { parseIssuesFile } from "@/features/planner/issues/planIssues";
import { featuresGateComplete, featuresSummary } from "@/features/planner/issues/featureList";
import { findPlanGaps } from "@/features/planner/lib/lintPlan";
import { findPlanInjections, injectionGate } from "@/features/planner/lib/planInjection";
import { deploymentDefined } from "@/features/planner/lib/deployConfig";
import { marketDefined } from "@/features/planner/lib/marketConfig";
import { transformationsConfirmed, type TransformationRow } from "@/features/planner/lib/transformations";
import { allSourcesConnected, migrationActive, dataModelSignals } from "@/features/planner/lib/sourceConfig";
import { unlockedSharedRepos } from "@/features/planner/issues/dependencies";
import { stagesFrom, activeIndex, currentGateReady } from "@/features/planner/stages/focusedPlan";
import { classifySignals, type ClassifyConfig } from "@/features/planner/lib/classifyConfig";

interface PlanGatesDeps {
  sections: Section[];
  /** The active blueprint's sections (stays in Planning; passed in as gate input). */
  planSecs: BlueprintStage[];
  ctxRequired: string[];
  publishRepos: string[];
  planFleet: Record<string, { streams: { id: string; repo: string }[] }>;
  planAutomations: Record<string, unknown[]>;
  featureIssues: unknown[];
  effectiveProjectId: string;
  requiresUi: boolean;
  uiCounts: { approved: number; total: number };
  featureState: ReturnType<typeof featuresSummary>;
  featureCycle: string[];
  confirmedSet: Set<string>;
  skippedSet: Set<string>;
  planDependencies: Parameters<typeof unlockedSharedRepos>[0];
  sourceCfg: Parameters<typeof migrationActive>[0];
  injectionHardGate: boolean;
  planInjectionAck: Record<string, string>;
  deployCfg: Parameters<typeof deploymentDefined>[0];
  /** The market-stage assessment (#2430) — drives the `marketDefined` gate signal. */
  marketCfg: Parameters<typeof marketDefined>[0];
  /** The transformations rows (#2509) — drive the `transformationsConfirmed` gate signal. */
  transformationRows: TransformationRow[];
  /** The planner's per-project classification (#3784) — drives the source/mcp/skills/automations
   *  visibility signals (all default OFF → those stages hidden until the planner opts in), plus the
   *  app-type / lifecycle signals (`appType:*`, `lifecycle:*`, `hasUserInterface`) a stage's
   *  `appliesWhen` keys on. */
  classifyCfg: ClassifyConfig | undefined;
  /** How many skills the project has (resolveSkills length) — the skills stage also shows when a
   *  project has >=1 skill even if the planner didn't pre-flag needsSkills (research -> skills). */
  projectSkillCount: number;
}

export function usePlanGates(deps: PlanGatesDeps) {
  const {
    sections, planSecs, ctxRequired, publishRepos, planFleet, planAutomations,
    featureIssues, effectiveProjectId, requiresUi, uiCounts, featureState, featureCycle,
    confirmedSet, skippedSet, planDependencies, sourceCfg, injectionHardGate, planInjectionAck,
    deployCfg, marketCfg, transformationRows, classifyCfg, projectSkillCount,
  } = deps;

  // The live snapshot the declarative section gates read.
  const stageState = useMemo(() => {
    const streams = planFleet[effectiveProjectId]?.streams ?? [];
    const issueCount =
      parseIssuesFile(sections.find(s => s.k === "issues")?.content ?? "").length + featureIssues.length;
    return derivePlanStageState({
      sections: sections.map(s => ({ k: s.k, state: s.state })),
      discoveryRequired: ctxRequired,
      repoCount: publishRepos.length,
      issueCount,
      fleetStreams: streams.length,
      // Unified role→profile model: every stream auto-gets its role's default profile at launch
      // (no per-stream generated profile to assign), so "profiles complete" simply means the fleet
      // has been planned — i.e. there are streams.
      fleetProfilesComplete: streams.length > 0,
      automationsAck: (planAutomations[effectiveProjectId]?.length ?? 0) > 0,
      // #3905: was hardcoded `false`, which made the Skills gate ("assign skills to the fleet")
      // UNSATISFIABLE — nothing ever set it true, so once the stage applied it blocked the plan
      // forever and triage became unreachable. Derived like `automationsAck` above: the fleet has
      // skills once the project resolves at least one. A project the planner flagged `needsSkills`
      // but assigned NO skills still blocks, which is exactly what the gate label means.
      skillsAck: projectSkillCount > 0,
      requiresUi,
      ui: uiCounts,
      // Routing dropped design files to the project completes the UI stage — recorded as a
      // confirmation of the `ui` section so it persists (#837).
      uiRouted: confirmedSet.has("ui"),
      // Features completes ONLY when every feature is populated AND the user has confirmed the set
      // (#plan-db) — `allConfirmed` (all-defined) alone used to auto-advance after a single feature.
      // Folding the user-confirm in here keeps the gate signal (`featuresConfirmed`) unchanged.
      features: { count: featureState.count, allConfirmed: featuresGateComplete(featureState, confirmedSet.has(FEATURES_KEY)) && featureCycle.length === 0 },
      // Dependencies (#1111/#1127): the Deploy gate passes once ≥1 library is locked in the manifest.
      dependencies: { count: planDependencies.length },
      // Source migration (#1205): the scan drives whether the source stage applies + its gate
      // signals, so the source-inferred schema can dictate features/structure.
      migrationSourceEnabled: migrationActive(sourceCfg),
      dataModelSignals: dataModelSignals(sourceCfg),
    });
  }, [sections, ctxRequired, publishRepos, planFleet, planAutomations, featureIssues, effectiveProjectId, requiresUi, uiCounts, featureState, featureCycle, confirmedSet, planDependencies, sourceCfg]);
  // lint-as-gate (#897 Phase 4b — lint-plan folded into the declarative gate). A WRITTEN section
  // (drafted/confirmed; pending ones aren't authored yet) must not carry a deliberate "fill this
  // in later" marker (TODO / TBD / FIXME / XXX / TKTK). Scanned ONLY over sections that belong to
  // the ACTIVE blueprint (so stale files from a prior blueprint can't block), and only those
  // markers — NOT ellipsis or the word "placeholder", which are normal prose and were
  // false-positiving (#918). Surfaced as `hasPlanGaps`; the gate requires it false, absent-safe.
  const hasPlanGaps = useMemo(() => {
    const enabled = new Set(planSecs.map((s) => s.key));
    const written: Record<string, string> = {};
    for (const s of sections) if (s.state !== "pending" && enabled.has(s.k)) written[`${s.k}.md`] = s.content ?? "";
    return findPlanGaps(written).some((g) => g.endsWith("unresolved placeholder"));
  }, [sections, planSecs]);
  // Plan-injection provenance gate (#1107): scan the planner-authored section prose for injected
  // instructions, then gate plan→fleet promotion. Acknowledge-to-clear by default; hard-block when
  // the `injectionHardGate` setting is on. Surfaced as a banner; `cleared` gates publish.
  const injectionGateState = useMemo(() => {
    const enabled = new Set(planSecs.map((s) => s.key));
    const written: Record<string, string> = {};
    for (const s of sections) if (s.state !== "pending" && enabled.has(s.k)) written[`${s.k}.md`] = s.content ?? "";
    return injectionGate(findPlanInjections(written), { hardGate: injectionHardGate, ackSig: planInjectionAck[effectiveProjectId] });
  }, [sections, planSecs, injectionHardGate, planInjectionAck, effectiveProjectId]);
  // User-skipped optional stages (#921) surface as `skipped:<key>` signals so the data-driven
  // gate model (`stageDone`) treats them as resolved.
  const skipSignals = useMemo(() => {
    const out: Record<string, boolean> = {};
    for (const k of skippedSet) out[skippedSignal(k)] = true;
    return out;
  }, [skippedSet]);
  // A gateless ("informational") section is done only once CONFIRMED (#664) — `stageDone` reads a
  // `confirmed:<key>` signal. Workspace those so a confirmed gateless stage (testing, cleanup, the data
  // stages, a user-authored stage, …) reads as complete and the frontier advances (#954).
  const confirmSignals = useMemo(() => {
    const out: Record<string, boolean> = {};
    for (const k of confirmedSet) out[confirmedSignal(k)] = true;
    return out;
  }, [confirmedSet]);
  const signals = useMemo(() => {
    // Shared-deps gate (#1429): every repo built by 2+ streams must have its deps locked; single-owner
    // repos (and no-fleet plans) auto-satisfy. Derived from the fleet streams' repos + the manifest.
    const repoStreams: Record<string, string[]> = {};
    for (const s of (planFleet[effectiveProjectId]?.streams ?? [])) { if (s.repo) (repoStreams[s.repo] ??= []).push(s.id); }
    const sharedDepsLocked = unlockedSharedRepos(planDependencies, repoStreams).length === 0;
    // The Structure/Plan gate (#1912): the feature DAG is defined (≥1 feature) and acyclic. This
    // replaced the old `featuresPhased` (every feature assigned a roadmap phase) — sequencing is now
    // expressed purely via feature `dependsOn`, with no milestone phases.
    const featuresDefined = featureState.count > 0 && featureCycle.length === 0;
    return { ...planStateToSignals(stageState), hasPlanGaps, featuresDefined, deploymentDefined: deploymentDefined(deployCfg), marketDefined: marketDefined(marketCfg), transformationsConfirmed: transformationsConfirmed(transformationRows), sharedDepsLocked, sourcesConnected: allSourcesConnected(sourceCfg), classified: classifyCfg !== undefined, needsMarket: !!classifyCfg?.needsMarket, needsSource: !!classifyCfg?.needsSource, needsMcp: !!classifyCfg?.needsMcp, needsAutomations: !!classifyCfg?.needsAutomations, needsSkills: !!classifyCfg?.needsSkills || projectSkillCount > 0, ...classifySignals(classifyCfg), ...skipSignals, ...confirmSignals };
  }, [stageState, hasPlanGaps, featureState, featureCycle, deployCfg, marketCfg, transformationRows, sourceCfg, skipSignals, confirmSignals, planFleet, effectiveProjectId, planDependencies, classifyCfg, projectSkillCount]);

  // Focused pane (#652): one stage at a time. `stages` derive from the blueprint sections +
  // signals; the active stage auto-follows the frontier (the user-pick SELECTION stays in Planning).
  const stages = useMemo(() => stagesFrom(planSecs, signals), [planSecs, signals]);
  const focusActiveIdx = useMemo(() => activeIndex(stages), [stages]);
  const focusGateReady = useMemo(() => currentGateReady(planSecs, signals), [planSecs, signals]);
  const planComplete = useMemo(() => planStagesComplete(planSecs, signals), [planSecs, signals]);
  const currentStage = stages[focusActiveIdx]?.key ?? "";
  const planStatusLabel = planComplete ? "complete" : currentStage ? "in_progress" : "starting";
  // Legacy alias kept for the publish/recovery readers (#854): the dynamic blueprint gate IS the
  // completion gate.
  const planReady = planComplete;

  return { injectionGateState, stages, focusActiveIdx, focusGateReady, planComplete, currentStage, planStatusLabel, planReady };
}

// usePlanMcpDownloads (#1474) — the planner's MCP download-confirmation queue, extracted verbatim
// from Planning.tsx. A blueprint / planner-assigned first-party MCP server can install from source;
// rather than cloning that third-party code silently, each not-yet-installed server is queued here
// and surfaced in a modal for the user to confirm. `enqueueMcpDownloads` is a stable callback safe
// to call from the blueprint effect AND the plan.db poll without staleness; `confirm` clones+builds
// the queue; `cancel` dismisses it (keeping the seen-set so skipped servers don't re-prompt).

import { useCallback, useRef, useState } from "react";
import { invoke } from "@tauri-apps/api/core";
import { catalogLink, repoNameFromLink } from "@/features/mcp";
import { type McpDownloadItem } from "@/features/planner/pane/McpDownloadModal";
import { MCP_CATALOG } from "@/shared/data/mcpCatalog";

export interface PlanMcpDownloads {
  /** Queue downloadable catalog servers (by name) for the confirmation modal, skipping any already
   *  installed or already queued. */
  enqueueMcpDownloads: (names: string[]) => Promise<void>;
  /** The pending download queue (rendered by McpDownloadModal). */
  mcpDownloads: McpDownloadItem[];
  /** Download (clone + build) every still-pending/failed queued server, advancing its row status. */
  confirmMcpDownloads: () => Promise<void>;
  /** Dismiss the modal: drop the queue but keep the seen-set so skipped servers don't re-prompt. */
  cancelMcpDownloads: () => void;
}

export function usePlanMcpDownloads(): PlanMcpDownloads {
  // Download-confirmation queue (#1055): the blueprint a project uses and the servers the planner
  // assigns can pull in first-party MCP servers that install from source. Instead of cloning that
  // third-party code silently, we queue each not-yet-installed server here and surface a modal with
  // its repo link; the user confirms before anything downloads. `mcpDownloadSeen` guards against
  // re-queuing the same server (so a re-applied blueprint / poll tick doesn't nag).
  const [mcpDownloads, setMcpDownloads] = useState<McpDownloadItem[]>([]);
  const mcpDownloadSeen = useRef<Set<string>>(new Set());

  // Queue downloadable catalog servers (by name) for the confirmation modal, skipping any already
  // installed or already queued. State-free (refs + functional setState) so it's a stable callback
  // safe to invoke from the blueprint effect AND the plan.db poll without staleness.
  const enqueueMcpDownloads = useCallback(async (names: string[]) => {
    const fresh: McpDownloadItem[] = [];
    for (const name of names) {
      const link = catalogLink(name);
      if (!link) continue; // not a downloadable first-party server
      const key = name.toLowerCase();
      if (mcpDownloadSeen.current.has(key)) continue;
      const repo = repoNameFromLink(link);
      try {
        const r = await invoke<{ downloaded: boolean; built: boolean }>("mcp_status", { name: repo });
        if (r.downloaded && r.built) { mcpDownloadSeen.current.add(key); continue; } // already installed
      } catch { /* not installed → prompt */ }
      mcpDownloadSeen.current.add(key);
      const cat = MCP_CATALOG.find((c) => c.name.toLowerCase() === key);
      fresh.push({ name, repo, link, desc: cat?.desc, install: cat?.install, status: "pending" });
    }
    if (fresh.length) setMcpDownloads((prev) => [...prev, ...fresh]);
  }, []);

  // Download (clone + build) every still-pending/failed queued server, advancing its row status.
  const confirmMcpDownloads = useCallback(async () => {
    const setStatus = (name: string, status: McpDownloadItem["status"]) =>
      setMcpDownloads((p) => p.map((d) => (d.name === name ? { ...d, status } : d)));
    const targets = mcpDownloads.filter((d) => d.status === "pending" || d.status === "error");
    await Promise.all(targets.map(async (it) => {
      setStatus(it.name, "downloading");
      try { await invoke("mcp_clone", { name: it.repo, url: it.link }); }
      catch { setStatus(it.name, "error"); return; }
      setStatus(it.name, "building");
      try {
        const r = await invoke<{ ok: boolean }>("mcp_build", { name: it.repo });
        setStatus(it.name, r.ok ? "ready" : "error");
      } catch { setStatus(it.name, "error"); }
    }));
  }, [mcpDownloads]);

  // Dismiss the modal: drop the queue but keep the seen-set so skipped servers don't immediately
  // re-prompt (the user can still install them later from the MCP screen).
  const cancelMcpDownloads = useCallback(() => setMcpDownloads([]), []);

  return { enqueueMcpDownloads, mcpDownloads, confirmMcpDownloads, cancelMcpDownloads };
}

// usePlanMcpManagement (#1474) — the planner's MCP install lifecycle, extracted verbatim from
// Planning.tsx (the download-confirmation queue is its own hook, usePlanMcpDownloads). Owns the
// disk-probe, the blueprint-attached-MCP scoping, the project + planner-session MCP context writes,
// and the toggle/add/build/remove handlers.
//
// `mcpInstallState` STAYS in Planning (it feeds the paneData memo); this hook only WRITES it via the
// passed `setMcpInstallState` (always functional updates), which breaks the paneData→probe render
// cycle with no behavior change. Call it immediately after paneData so `mcpServersUi` is available.

import { useCallback, useEffect, useMemo, type Dispatch, type SetStateAction } from "react";
import { invoke } from "@tauri-apps/api/core";
import { fireInvoke } from "@/shared/lib/core/safeInvoke";
import { useAppStore } from "@/store";
import { applyBlueprintMcp, collectBlueprintMcp } from "@/features/planner/blueprints/blueprintMcp";
import { writeProjectMcpContext } from "@/features/planner/lib/mcpContext";
import { catalogLink, repoNameFromLink, mcpRepoName } from "@/features/mcp";
import { applyMcpAssign } from "@/features/planner/lib/planExtensions";
import { MCP_CATALOG } from "@/shared/data/mcpCatalog";
import { roleCapability, roleWriteRules, roleDeniedCommands } from "@/shared/lib/session/sessionRoles";
import { TURN_ACCOUNTING_HOOKS } from "@/shared/lib/session/turnHooks";
import { resolveAllInstalledMcp, toSessionPayloads, mcpAllowRules } from "@/features/mcp";
import { type McpInstallState } from "@/features/planner/lib/mcpPaneData";
import { type Blueprint } from "@/features/planner/stages/blueprints";

type StoreMcpServers = Parameters<typeof resolveAllInstalledMcp>[0];
/** The probe only reads id/name/downloadable off paneData.mcpServers. */
interface ProbeServer { id: string; name: string; downloadable?: boolean }

interface McpManagementDeps {
  effectiveProjectId: string;
  effectiveBlueprintId: string;
  blueprints: Blueprint[];
  planningDir: string;
  /** paneData.mcpServers — the UI server list the probe filters for downloadable servers. */
  mcpServersUi: ProbeServer[] | undefined;
  /** The store's mcpServers value — drives the installed-server context writes. */
  mcpServers: StoreMcpServers;
  /** Writes install status (functional updates only — the value lives in Planning, feeding paneData). */
  setMcpInstallState: Dispatch<SetStateAction<McpInstallState>>;
  /** Queue first-party MCP servers for the download-confirmation modal (from usePlanMcpDownloads). */
  enqueueMcpDownloads: (names: string[]) => Promise<void>;
}

export interface PlanMcpManagement {
  onToggleMcp: (id: string) => void;
  onRemoveMcp: (id: string) => void;
  onAddMcp: (input: string) => void;
  onBuildMcp: (s: { id: string; name: string; status: string }) => Promise<void>;
}

export function usePlanMcpManagement(deps: McpManagementDeps): PlanMcpManagement {
  const { effectiveProjectId, effectiveBlueprintId, blueprints, planningDir, mcpServersUi, mcpServers, setMcpInstallState, enqueueMcpDownloads } = deps;

  // Probe each downloadable MCP server's on-disk state so the pane opens with real status
  // (downloaded? built?) instead of "available" for already-installed servers.
  useEffect(() => {
    const probe = mcpServersUi?.filter(s => s.downloadable) ?? [];
    if (probe.length === 0) return;
    let cancelled = false;
    Promise.all(probe.map(async (s) => {
      try {
        const r = await invoke<{ downloaded: boolean; built: boolean }>("mcp_status", { name: mcpRepoName(s.name) });
        return [s.id, r.built ? "ready" : r.downloaded ? "downloaded" : "available"] as const;
      } catch { return [s.id, "available"] as const; }
    })).then((rows) => {
      if (cancelled) return;
      setMcpInstallState((prev) => {
        const next = { ...prev };
        // Don't clobber an in-flight downloading/building status with a probe result.
        for (const [id, st] of rows) if (next[id] !== "downloading" && next[id] !== "building") next[id] = st;
        return next;
      });
    });
    return () => { cancelled = true; };
    // Re-probe only when the set of downloadable server ids changes.
  }, [mcpServersUi?.filter(s => s.downloadable).map(s => s.id).join(",")]); // eslint-disable-line react-hooks/exhaustive-deps

  // Scope the active blueprint's attached MCP servers to this project (#897 Phase 2), so the
  // planner + fleet get the tools the blueprint declares. Idempotent (applyMcpAssign enables +
  // scopes existing, or adds). The downloadable (first-party) ones are queued for the
  // download-confirmation modal (#1055) rather than cloned silently. Re-runs when the project or
  // the blueprint's attached-MCP set changes.
  const bpMcpKey = useMemo(() => {
    const bp = blueprints.find(b => b.id === effectiveBlueprintId);
    return bp ? collectBlueprintMcp(bp).join("\n") : "";
  }, [blueprints, effectiveBlueprintId]);
  useEffect(() => {
    if (!effectiveProjectId || !bpMcpKey) return;
    const store = useAppStore.getState();
    const bp = store.blueprints.find(b => b.id === effectiveBlueprintId);
    if (!bp) return;
    void enqueueMcpDownloads(applyBlueprintMcp(store, bp, effectiveProjectId, store.bscBaseDir));
  }, [bpMcpKey, effectiveProjectId, effectiveBlueprintId, enqueueMcpDownloads]);

  // Write the planner's live extensions.md — the installed MCP servers it can call + the per-worker
  // assignment directive (#1054). Supersedes the static catalogue setup_workspaces used to write;
  // re-runs whenever the installed-server set or the project changes.
  const installedMcpKey = useMemo(
    () => resolveAllInstalledMcp(mcpServers).map((e) => `${e.id}:${e.name}`).join("\n"),
    [mcpServers],
  );
  useEffect(() => {
    if (!effectiveProjectId) return;
    void writeProjectMcpContext({ projectKey: effectiveProjectId, servers: resolveAllInstalledMcp(useAppStore.getState().mcpServers) })
      .catch((e) => console.warn("writeProjectMcpContext failed:", e));
  }, [installedMcpKey, effectiveProjectId]);

  // Keep the planner session's .mcp.json current as servers are downloaded (#1054). Claude loads MCP
  // config at startup, so a newly downloaded server is picked up on the planner's next launch /
  // resume; this keeps the file ready. No-op until the planner dir is known.
  useEffect(() => {
    if (!planningDir) return;
    const cap = roleCapability("director");
    const write = roleWriteRules(cap);
    const mcp = toSessionPayloads(resolveAllInstalledMcp(useAppStore.getState().mcpServers), []).mcp;
    fireInvoke("ensure_session_settings", {
      cwd:             planningDir,
      allowedCommands: [],
      deniedCommands:  roleDeniedCommands(cap),
      mcpServers:      mcp,
      // Turn accounting (#3455): re-assert on the MCP refresh too. replacePermissions:true would
      // otherwise clear the launch-time turn hooks and re-blind the planner's cost.
      hooks:           TURN_ACCOUNTING_HOOKS,
      // Auto-approve every MCP server the planner is given (Research included) so calling them
      // while planning never hits a per-tool prompt — replacePermissions:true here would otherwise
      // drop the launch-time rules, so this refresh must re-assert them too.
      allowToolRules:  [...write.allow, "Read", "WebFetch", ...mcpAllowRules(mcp)],
      denyToolRules:   write.deny,
      replacePermissions: true,
    }, (e: unknown) => console.warn("planner mcp refresh failed:", e));
  }, [installedMcpKey, planningDir]);

  // ── MCP stage handlers (#878) ──────────────────────────────────────────────
  const onToggleMcp = useCallback((id: string) => useAppStore.getState().toggleMcpServer(id), []);
  const onRemoveMcp = useCallback((id: string) => useAppStore.getState().removeMcpServer(id), []);
  const onAddMcp = useCallback((input: string) => {
    const store = useAppStore.getState();
    // A bare catalog name maps to its template; anything with a scheme is a remote URL; else a
    // stdio command line. New servers are enabled + scoped to this project so the fleet gets them.
    const link = catalogLink(input);
    if (link || MCP_CATALOG.some(c => c.name.toLowerCase() === input.toLowerCase())) {
      const name = MCP_CATALOG.find(c => c.name.toLowerCase() === input.toLowerCase())?.name ?? input;
      applyMcpAssign(store, name, effectiveProjectId, store.bscBaseDir);
      if (link) fireInvoke("mcp_clone", { name: repoNameFromLink(link), url: link });
      return;
    }
    const isUrl = /^https?:\/\//i.test(input);
    store.addMcpServer({
      name: input.split(/\s+/)[0].slice(0, 40) || "server", enabled: true, projects: [effectiveProjectId],
      transport: isUrl ? "http" : "stdio",
      ...(isUrl ? { url: input } : { command: input.split(/\s+/)[0], args: input.split(/\s+/).slice(1).join(" ") }),
      env: [],
    });
  }, [effectiveProjectId]);
  const onBuildMcp = useCallback(async (s: { id: string; name: string; status: string }) => {
    const repo = mcpRepoName(s.name);
    const link = catalogLink(s.name);
    // Ensure it's downloaded, then build, tracking status so the pane reflects progress.
    if (link && (s.status === "available")) {
      setMcpInstallState(p => ({ ...p, [s.id]: "downloading" }));
      try { await invoke("mcp_clone", { name: repo, url: link }); }
      catch { setMcpInstallState(p => ({ ...p, [s.id]: "available" })); return; }
    }
    setMcpInstallState(p => ({ ...p, [s.id]: "building" }));
    try {
      const r = await invoke<{ ok: boolean }>("mcp_build", { name: repo });
      setMcpInstallState(p => ({ ...p, [s.id]: r.ok ? "ready" : "error" }));
    } catch {
      setMcpInstallState(p => ({ ...p, [s.id]: "error" }));
    }
  }, [setMcpInstallState]);

  return { onToggleMcp, onRemoveMcp, onAddMcp, onBuildMcp };
}

// usePlanPublish (#1490) — the publish → GitHub + triage-launch + GitHub→plan.db recovery cluster,
// extracted verbatim from Planning.tsx. Owns the triage/publish/recovery state (no render loop —
// just callbacks + a recovery probe effect); takes the plan data it reads as a params object so the
// bodies move unchanged. Returns the callbacks + the state the JSX consumes.

import { useState, useEffect } from "react";
import { invoke } from "@tauri-apps/api/core";
import { safeInvoke, fireInvoke } from "@/shared/lib/core/safeInvoke";
import { bscJson, bscWrite } from "@/shared/lib/core/bsc";
import { useAppStore } from "@/store";
import { useConfirmDialog } from "@/shared/ui/overlay/promptDialog";
import type { Section } from "@/features/planner/github/ghStructure";
import { type GhStatusMap } from "@/features/planner/session/GitHubStructureCard";
import { deriveProjectTitle } from "@/features/planner/session/projectTitle";
import { parseFeaturesFile } from "@/features/planner/issues/featureList";
import { parseDependencyManifest, depsForRepo } from "@/features/planner/issues/dependencies";
import { buildWorkerScope, toWorkerUiPairing } from "@/features/planner/fleet/workerScope";
import { effectiveHarness } from "@/shared/lib/core/llmConfig";
import { type PlanIssue } from "@/features/planner/issues/planIssues";
import { pruneCompletedStreams, doneIssueRefs } from "@/shared/lib/fleet/streamCompletion";
import { resolveClosedRefs } from "@/features/glance";
import { withDerivedStreamIssues } from "@/features/planner/fleet/planFleet";
import { teamRoleStreams } from "@/features/planner/fleet/teamFleet";
import { recoverIssues, type GitHubIssueLike } from "@/features/planner/issues/recoverIssues";
import { removeDbProject } from "@/features/planner/list/projectsDbBridge";
import { publishFleetRoster } from "@/shared/lib/fleet/fleetRoster";
import { canLaunchTriage, publishBlockReason } from "@/shared/lib/github/projectSync";
import {
  type GhApi, type Upd, seedPublishStatus,
  publishRepositories, scaffoldRepositories, ensureProjectBoard, createIssues, applyStreamLabels,
  materializeIssues,
} from "@/features/planner/session/publishSteps";

export type PublishPhase = "idle" | "running" | "done" | "error";

type Store = ReturnType<typeof useAppStore.getState>;

export interface PlanPublishDeps {
  githubToken: string;
  publishRepos: string[];
  injectionGateState: { cleared: boolean; findings: unknown[]; mode: string };
  sections: Section[];
  planningTitle: string;
  activeProjectName: string;
  planFleet: Store["planFleet"];
  effectiveProjectId: string;
  activeProjectId: Store["activeProjectId"];
  activeProjectNumber: Store["activeProjectNumber"];
  planFeatures: ReturnType<typeof parseFeaturesFile>;
  planDependencies: ReturnType<typeof parseDependencyManifest>["dependencies"];
  depManifest: ReturnType<typeof parseDependencyManifest>;
  repoPublic: Store["repoPublic"];
  reposPublic: Record<string, boolean>;
  projectTitle: string;
  planReady: boolean;
  visible: boolean;
  addProjectRepo: Store["addProjectRepo"];
  fleetStartProject: Store["fleetStartProject"];
}

export function usePlanPublish(deps: PlanPublishDeps) {
  const {
    githubToken, publishRepos, injectionGateState, sections, planningTitle,
    activeProjectName, planFleet, effectiveProjectId, activeProjectId, activeProjectNumber,
    planFeatures, planDependencies, depManifest, repoPublic, reposPublic,
    projectTitle, planReady, visible, addProjectRepo, fleetStartProject,
  } = deps;

  const [triaging, setTriaging] = useState(false);
  const [triageError, setTriageError] = useState<string | null>(null); // launch-failure surfacing (#551)
  const [triageNote, setTriageNote] = useState<string | null>(null);   // progress-gated relaunch summary (#1004)
  // GitHub→plan.db recovery (#plan-db): how many planner-published issues GitHub holds when the
  // local plan.db is empty (machine switch / data loss), and whether a recovery is in flight.
  const [recoverable, setRecoverable] = useState(0);
  const [recovering, setRecovering] = useState(false);
  const [publishPhase, setPublishPhase] = useState<PublishPhase>("idle");
  // Live status of each GitHub object, keyed by the ids in buildGhStructure.
  const [ghStatus, setGhStatus] = useState<GhStatusMap>({});
  // Confirm + clear stale warden quarantines before a triage relaunch (a denied command from a prior
  // run otherwise persists and immediately re-pauses the relaunched worker). `quarantineDialog` is the
  // self-rendering modal node the JSX mounts.
  const { confirm, dialog: quarantineDialog } = useConfirmDialog();

  async function launchTriage() {
    const fleet = planFleet[effectiveProjectId];
    // Pre-flight gate (#444/#551) — mirror the button's gate so a programmatic / Enter-key
    // path can't launch against an unpublished or plan-incomplete project. (Restored: the
    // refactor had weakened this to a repos/fleet-only check.)
    if (!canLaunchTriage({
      published: !!activeProjectId,
      hasRepos: publishRepos.length > 0,
      hasFleet: !!fleet && fleet.streams.length > 0,
      busy: triaging,
      planReady,
    })) return;
    // A stale warden quarantine from a PRIOR run persists (in quarantinedPanes + the bsc-audit log)
    // and would immediately re-pause the relaunched worker. On triage: show the user WHY each worker
    // was quarantined, then clear those flags and stamp a warden "since" floor so the relaunch is clean.
    const projQuarantines = Object.entries(useAppStore.getState().quarantinedPanes)
      .filter(([p]) => p.startsWith(`${effectiveProjectId}:`));
    if (projQuarantines.length > 0) {
      const reasons = projQuarantines.map(([, info]) => `${info.streamId} (${info.summary})`).join("; ");
      const ok = await confirm({
        title: projQuarantines.length === 1 ? "Clear worker quarantine?" : `Clear ${projQuarantines.length} worker quarantines?`,
        message: `${projQuarantines.length === 1 ? "A worker was" : `${projQuarantines.length} workers were`} `
          + `quarantined and paused — ${reasons}. Relaunching clears `
          + `${projQuarantines.length === 1 ? "it and resumes the worker" : "them and resumes the workers"}.`,
        confirmLabel: "Clear & relaunch",
        cancelLabel: "Cancel",
      });
      if (!ok) return;
    }
    // Always stamp the warden floor for the project's panes on relaunch (even with nothing currently
    // flagged) so a stale denied command that hasn't tripped the warden yet also can't re-pause.
    {
      const relaunchPanes = (fleet?.streams ?? []).map((st) => `${effectiveProjectId}:${st.id}`);
      useAppStore.getState().clearProjectQuarantine(effectiveProjectId, relaunchPanes, Date.now());
    }
    setTriageError(null);
    setTriageNote(null);
    setTriaging(true);
    try {
      // Materialize the project hub on disk (#2997 C, epic #2993): planning ran in an ephemeral
      // per-project workspace, so this creates projects/<key>/ and moves the planner's authored files
      // in — BEFORE any director/worker cwd (the hub dir or a worktree beneath it) resolves to it.
      // Idempotent: an already-materialized hub or a re-launch is a no-op. Fail-CLOSED — without the
      // hub the director + worktree cwds don't exist, so surface the failure and abort the launch
      // rather than dropping the fleet into a missing directory.
      try {
        await invoke("materialize_hub", { projectKey: effectiveProjectId });
      } catch (e) {
        setTriageError(`launch failed — could not materialize the project hub: ${String(e)}`);
        return;
      }
      // #1988: when the sandbox is on AND the fleet runs on the model-agnostic bsc-agent harness (the
      // only runtime baked into the sealed distro), the whole fleet launches INSIDE the WSL2 cage —
      // the hub is relocated to the distro's ext4, repos are cloned + worktrees created in-distro, and
      // every pane spawns via `wsl -d <distro>`. Otherwise it's the normal host launch.
      const store0 = useAppStore.getState();
      const sandbox = store0.sandboxConsoles === true
        && effectiveHarness(store0.llmProvider, store0.fleetHarness ?? "claude") === "bsc-agent";
      const SANDBOX_DISTRO = "bsc-agent-sandbox";
      // Host clones seed the on-disk repo list the UI reads; skip them for a sandboxed launch (repos
      // are git-cloned in-distro by ensure_sandbox_worktree — nothing lands on the Windows host).
      if (!sandbox) await Promise.all(publishRepos.map(fullName =>
        invoke<string>("clone_repo", { project: effectiveProjectId, fullName })
          .then(() => addProjectRepo(activeProjectId ?? effectiveProjectId, fullName))
          .catch(e => console.error(`clone ${fullName} failed:`, e)),
      ));
      // Each worker auto-runs under its ROLE's default profile at launch (worker → Autonomous,
      // director → Read-only review) — no per-stream profile to materialize here anymore.
      const fullPlan = useAppStore.getState().planFleet[effectiveProjectId] ?? fleet;
      // Progress-gated relaunch (#1004): read each issue's status from plan.db and DON'T restart a
      // worker whose issues are all complete/verified — it already finished. Prune those streams (their
      // worktrees/branches persist untouched); launch only the streams with outstanding work, plus the
      // director if enabled. On a first launch nothing is done, so every stream stays active.
      const dbIssues = await bscJson<PlanIssue[]>(effectiveProjectId, ["plan", "list", "--full", "--json"], []);
      // #1957: completed workers no longer skip — they relaunch INTO maintenance (alive + ready for the
      // director to dispatch new lane work), so launch BOTH active and maintenance streams. The
      // maintenance set drives a maintenance scope banner (buildWorkerScope) so they stand by, not rebuild.
      // #4103: plan.db's issue rows can be empty for a fleet assembled outside a full planner run, in
      // which case `doneIssueRefs` is empty and NO stream ever prunes as complete. GitHub's closed set
      // is the other evidence source; either one calling a ref done makes it done.
      const closedRefs = await resolveClosedRefs(fullPlan.streams);
      const done = new Set([...doneIssueRefs(dbIssues), ...closedRefs]);
      const { active, maintenance } = pruneCompletedStreams(fullPlan.streams, done);
      const maintenanceIds = new Set(maintenance.map(s => s.id));
      // #2611: a stream with no resolvable repo stays VISIBLE in the plan but can't spawn a worktree —
      // skip it here (rather than aborting the fail-closed launch on a broken ensure_worktree) and
      // surface which streams still need a repo assigned, so the gap is seen, not swallowed.
      // #2615: a stream can reach launch with an empty `issues[]` even though issues name it as their
      // owning `stream` — enrich each stream's issue list from the plan.db issues so a worker launches
      // with its concrete task list (feeding BOTH the scope below and the kickoff via fleetStartProject),
      // not the "(none yet — ask the director)" placeholder. A stream that already lists issues is kept.
      const launchable = withDerivedStreamIssues([...active, ...maintenance].filter(st => st.repo), dbIssues);
      const noRepo = [...active, ...maintenance].filter(st => !st.repo);
      // Team-driven fleet (#3101/#3103): a project's TEAM contributes its ROLE-ACTOR sessions (curator,
      // documentor, reviewer, tester, juror, issuer) — one per team position bound to such a persona,
      // deduped vs the planner's own streams. They run at the project HUB (no repo → no worktree; the
      // `fleetStartProject` repo-less branch routes them there), so they compose in AFTER `launchable`
      // and are deliberately NOT part of the worktree-creation loop below.
      const teamStore = useAppStore.getState();
      const projectTeam = teamStore.blueprints.find(b => b.id === teamStore.projectBlueprintId[effectiveProjectId])?.team;
      const roleStreams = teamRoleStreams(projectTeam, teamStore.personas, fullPlan.streams);
      const launchPlan = { ...fullPlan, streams: [...launchable, ...roleStreams] };
      if (launchPlan.streams.length === 0 && !launchPlan.director.enabled) {
        setTriageError(noRepo.length > 0
          ? `No workers to launch — ${noRepo.length} stream${noRepo.length === 1 ? "" : "s"} (${noRepo.map(s => s.id).join(", ")}) need a repo assigned.`
          : "No workers to launch.");
        return;
      }
      const launchNotes: string[] = [];
      if (noRepo.length > 0) {
        launchNotes.push(`${noRepo.length} stream${noRepo.length === 1 ? "" : "s"} `
          + `(${noRepo.map(s => s.id).join(", ")}) skipped — no repo assigned`);
      }
      if (maintenance.length > 0) {
        launchNotes.push(`${maintenance.length} completed worker${maintenance.length === 1 ? "" : "s"} `
          + `(${maintenance.map(s => s.id).join(", ")}) relaunching into maintenance`
          + (active.length > 0 ? `; ${active.length} active` : ""));
      }
      if (launchNotes.length > 0) setTriageNote(launchNotes.join(". ") + ".");
      // The project's {kit, theme} pairing (#2489): plan.db's `ui` blob (the planner's per-project
      // record, `bsc plan ui set` in the Test UI stage) with the project blueprint's pin filling
      // whatever it doesn't set — inlined into every worker's scope as the UI-palette lock block
      // (token layer read-only; palette = the swappable theme.css).
      const uiBlob = await bscJson<{ kit?: { id?: string; version?: string } | null; themeId?: string } | null>(
        effectiveProjectId, ["plan", "ui", "get", "--json"], null);
      const storeUi = useAppStore.getState();
      const uiPairing = toWorkerUiPairing(
        uiBlob, storeUi.blueprints.find(b => b.id === storeUi.projectBlueprintId[effectiveProjectId])?.uiKit);
      // Create each worker's git worktree FAIL-CLOSED (#551/#359): if any can't be created,
      // abort the launch so no agent starts in a fallback dir. (Restored: the refactor had
      // weakened this to a non-fatal .catch that let the launch continue.)
      // Only the repo'd WORKER streams get a worktree — the team's hub role-actors (repo-less) are
      // excluded (they run at the hub, no isolated tree). `launchable` is exactly those worker streams.
      const worktreeResults = await Promise.all(launchable.map(st => {
        // Seed each worktree's CLAUDE.local.md with the worker's SCOPE (owns/issues/deps) plus its
        // repo's LOCKED dependency manifest (#1111), not the full plan — the worktree lives outside
        // the hub so the planner spec is no longer an ancestor (#844). In-distro when sandboxed
        // (ensure_sandbox_worktree clones the repo + adds the worktree on the distro's ext4, #1988).
        const scopeMd = buildWorkerScope(st, depsForRepo(planDependencies, st.repo), maintenanceIds.has(st.id), uiPairing);
        const call = sandbox
          ? invoke<string>("ensure_sandbox_worktree", { projectKey: effectiveProjectId, repo: st.repo, agentId: st.id, scopeMd, token: githubToken })
          : invoke<string>("ensure_worktree", { projectKey: effectiveProjectId, repo: st.repo, agentId: st.id, scopeMd });
        return call
          .then(path => ({ id: st.id, path, err: null as string | null }))
          .catch(e => ({ id: st.id, path: null as string | null, err: String(e) }));
      }));
      const failed = worktreeResults.filter(r => r.err || !r.path);
      if (failed.length > 0) {
        setTriageError(`launch failed — ${failed[0].id}: ${failed[0].err ?? "empty path"}`);
        return;
      }
      // Carry the authoritative absolute paths into fleetStartProject (#905) so each pane's
      // cwd comes from the Rust backend, not the async-loaded `bscBaseDir` mirror (which, when
      // empty/malformed, silently drops every session at the user's home dir). Workers use the
      // worktree path ensure_worktree just returned; the director uses the hub dir.
      const worktreePaths: Record<string, string> = {};
      for (const r of worktreeResults) if (r.path) worktreePaths[r.id] = r.path;
      // The director's cwd is the hub. Sandboxed → relocate the host hub onto the distro's ext4 and use
      // its distro-native path (setup_sandbox_hub); otherwise the on-host hub dir (#905).
      const hubPath = sandbox
        ? await safeInvoke<string>("setup_sandbox_hub", { key: effectiveProjectId }, "")
        : await safeInvoke<string>("project_dir_path", { projectKey: effectiveProjectId }, "");
      // Give the director its standing protocol at the hub (#375) so it gets the bsc-fleet
      // roster instruction + answers worker questions (the refactor dropped this call; #734).
      if (launchPlan.director.enabled) {
        await safeInvoke("ensure_director_protocol", { projectKey: effectiveProjectId }, undefined,
          e => console.error("director protocol failed:", e));
      }
      const roster = fleetStartProject(projectTitle, launchPlan, effectiveProjectId, { hubPath, worktreePaths, wslDistro: sandbox ? SANDBOX_DISTRO : undefined });
      publishFleetRoster(effectiveProjectId, roster); // #734: hub fleet.roster.tsv for bsc-fleet
    } catch (e) {
      console.error("fleet launch failed:", e);
    } finally {
      setTriaging(false);
    }
  }

  /** The LOCAL commit (#3280) — materialize the plan's issues into plan.db and mark the project active,
   *  with NO GitHub round-trip. This is what lets the fleet launch offline: `activeProjectId` set to the
   *  local project key flips `published` true (`canLaunchTriage`) and works as a key everywhere; a later
   *  publish upgrades it to the GitHub node id over the SAME plan.db rows (upsert-by-ref, no dupes).
   *  Shares publish's injection gate — never promote unreviewed markers to the fleet. */
  async function commitLocal() {
    if (!injectionGateState.cleared) {
      const n = injectionGateState.findings.length;
      setTriageError(injectionGateState.mode === "blocked"
        ? `Commit blocked: ${n} possible prompt-injection marker${n !== 1 ? "s" : ""} in the plan must be removed (hard-block is on in Settings).`
        : `Review the ${n} possible prompt-injection marker${n !== 1 ? "s" : ""} flagged in the plan, then acknowledge them before committing.`);
      return;
    }
    setTriageError(null);
    const featuresContent = sections.find(s => s.k === "features")?.content ?? "";
    await materializeIssues(featuresContent, { upsertIssue: (iss) => bscWrite(effectiveProjectId, ["plan", "add"], iss) });
    const goalContent  = sections.find(s => s.k === "goal")?.content ?? "";
    const projectTitle = deriveProjectTitle(planningTitle, goalContent, activeProjectName);
    // The local key IS activeProjectId here (no GitHub number) — publish later overwrites it with the
    // ProjectV2 node id. Reopening from the board derives the hub key from the name, so nothing bridges.
    useAppStore.getState().setActiveProjectMeta(effectiveProjectId, projectTitle, publishRepos[0] ?? "", 0, publishRepos);
  }

  async function handlePublish() {
    // #3280 local-first: with no GitHub token, "publish" commits the plan LOCALLY (plan.db) instead of
    // erroring — the fleet can then launch offline. Publishing to GitHub stays the optional path when
    // connected. (publishBlockReason's no-token case is now unreachable from here; the no-repo case
    // below still fires when connected.)
    if (!githubToken) { await commitLocal(); return; }
    // Don't fail silently (#969): surface WHY publish can't proceed, so the user isn't left thinking
    // they published when nothing happened (which then leaves the fleet-launch button locked with no
    // explanation). The common case is a blueprint with no Repos stage ⇒ no repo ever linked.
    const blocked = publishBlockReason({ hasToken: !!githubToken, repoCount: publishRepos.length });
    if (blocked) { setTriageError(blocked); return; }
    // #1107: never promote a plan with unreviewed / hard-blocked injection markers to the fleet.
    if (!injectionGateState.cleared) {
      const n = injectionGateState.findings.length;
      setTriageError(injectionGateState.mode === "blocked"
        ? `Publish blocked: ${n} possible prompt-injection marker${n !== 1 ? "s" : ""} in the plan must be removed (hard-block is on in Settings).`
        : `Review the ${n} possible prompt-injection marker${n !== 1 ? "s" : ""} flagged in the plan, then acknowledge them before publishing.`);
      return;
    }
    setTriageError(null);
    const token = githubToken;

    const repos        = publishRepos;
    const goalContent  = sections.find(s => s.k === "goal")?.content ?? "";
    const projectTitle = deriveProjectTitle(planningTitle, goalContent, activeProjectName);
    const projectDesc  = goalContent.split(/\n/)[0].slice(0, 350);
    const fleet        = planFleet[effectiveProjectId];
    const streams      = fleet?.streams ?? [];

    // Seed every node as "planned" so the card shows the full structure upfront.
    const status = seedPublishStatus({ repos, streams });
    setGhStatus({ ...status });
    setPublishPhase("running");

    let anyError = false;
    const upd: Upd = (id, patch) => {
      status[id] = { ...(status[id] ?? { status: "planned" }), ...patch };
      if (patch.status === "error") anyError = true;
      setGhStatus({ ...status });
    };

    // The GitHub transport — the same closures the steps consume (injected so they're testable).
    const api: GhApi = {
      gql: (query, variables) => invoke<Record<string, unknown>>("github_graphql", { token, query, variables }),
      rest: <T,>(path: string) => invoke<T>("github_request", { token, path }),
      post: <T,>(path: string, body: unknown) => invoke<T>("github_post", { token, path, body }),
      put: (path, body) => invoke("github_put", { token, path, body }),
      patch: (path, body) => invoke("github_patch", { token, path, body }),
    };

    try {
      // 1. Repositories — verify/create.
      const { repoNodeIds, viewerLogin } = await publishRepositories(api, upd, {
        repos, projectDesc, repoPublic, reposPublic, effectiveProjectId,
      });

      // 1b. Repo presentation — description/topics/README/community files + locked dep manifests.
      await scaffoldRepositories(api, upd, {
        repos, projectDesc, projectTitle, goalContent,
        stackText: sections.find(s => s.k === "stack")?.content ?? "",
        scopeText: sections.find(s => s.k === "scope")?.content ?? "",
        archText:  sections.find(s => s.k === "architecture")?.content ?? "",
        features: planFeatures.map(f => ({ name: f.name, behavior: f.behavior })),
        planDependencies, registries: depManifest.registries,
      });

      // 2. Project board — reuse or create; the store writes for a new board happen here in the hook.
      const board = await ensureProjectBoard(api, upd, {
        activeProjectId, activeProjectNumber, repos, viewerLogin, projectTitle, repoNodeIds,
      });
      const projectId = board.projectId;
      if (board.created) {
        const pv = board.created;
        const store = useAppStore.getState();
        // Reflect in the store so the projects list + future syncs treat it as existing.
        store.setActiveProjectMeta(pv.id, projectTitle, repos[0] ?? "", pv.number, repos);
        // No node-id → key alias write anymore (#2409): reopening from the board DERIVES the hub
        // key from the project's name (`projectSlug(title)`), so publish records nothing to bridge.
        // Mark the hub published in place (#922) — the hub never moves, so --continue history survives.
        fireInvoke("mark_published", { projectKey: effectiveProjectId }, (e) => console.warn("mark_published failed (Projects page reconciles it):", e));
        // Drop the store's draft entry so the project can't linger as a ghost draft card, and mirror
        // that removal into the durable projects DB (#2995) so the published project doesn't re-surface
        // as a draft from the DB union. Fire-and-forget; degrades silently.
        store.removeDraftProject(effectiveProjectId);
        void removeDbProject(effectiveProjectId);
      }

      // 3. Issues — features → issues, on the board, assigned, sub-issues nested (no milestones, #1912).
      await createIssues(api, upd, {
        repos, featuresContent: sections.find(s => s.k === "features")?.content ?? "",
        projectId, streams, viewerLogin,
      }, {
        upsertIssue: (iss) => bscWrite(effectiveProjectId, ["plan", "add"], iss),
        setIssueIdentity: (ref, ghNumber, ghNodeId) =>
          bscWrite(effectiveProjectId, ["plan", "link", ref], { ghNumber, ghNodeId }),
        loadIssues: () => bscJson<PlanIssue[]>(effectiveProjectId, ["plan", "list", "--full", "--json"], []),
      });

      // 4. Stream labels.
      await applyStreamLabels(api, upd, { streams });

      setPublishPhase(anyError ? "error" : "done");
    } catch (e) {
      console.error("publish failed", e);
      setPublishPhase("error");
    }
  }

  // GitHub → plan.db recovery (#plan-db). The mirror of handlePublish: pull each repo's
  // planner-published issues back into the plan store so a lost or machine-switched plan.db
  // rehydrates from the durable GitHub copy. Paginates issues (state=all), drops PRs, and upserts
  // each reconstructed PlanIssue (ref/dependsOn from the hidden marker, stream from the label,
  // status from open/closed). The 2s section poll reflects the DB afterward.
  async function handleRecover() {
    if (!githubToken || publishRepos.length === 0 || recovering) return;
    setRecovering(true);
    setTriageError(null);
    const token = githubToken;
    const rest = <T,>(path: string) => invoke<T>("github_request", { token, path });
    try {
      let total = 0;
      for (const repo of publishRepos) {
        const rows: GitHubIssueLike[] = [];
        for (let page = 1; page <= 20; page++) {
          const batch = await rest<GitHubIssueLike[]>(`repos/${repo}/issues?state=all&per_page=100&page=${page}`)
            .catch(() => [] as GitHubIssueLike[]);
          if (!batch || batch.length === 0) break;
          rows.push(...batch);
          if (batch.length < 100) break; // last page
        }
        for (const iss of recoverIssues(rows, repo)) {
          await bscWrite(effectiveProjectId, ["plan", "add"], iss);
          total++;
        }
      }
      setRecoverable(0);
      if (total === 0) setTriageError("recover — GitHub had no planner-published issues for these repos");
    } catch (e) {
      setTriageError(`recover failed — ${String(e)}`);
    } finally {
      setRecovering(false);
    }
  }

  // Offer recovery when the local plan.db is empty but GitHub holds planner-published issues (the
  // machine-switch / data-loss case). Probes the first repo for issues carrying the ref marker and
  // surfaces the banner; the recovery itself stays user-initiated.
  useEffect(() => {
    let cancelled = false;
    (async () => {
      if (!visible || !githubToken || publishRepos.length === 0) { setRecoverable(0); return; }
      const dbIssues = await bscJson<PlanIssue[]>(effectiveProjectId, ["plan", "list", "--full", "--json"], []);
      if (cancelled) return;
      if ((dbIssues?.length ?? 0) > 0) { setRecoverable(0); return; } // db already populated — nothing to recover
      const rows = await safeInvoke<GitHubIssueLike[]>("github_request", {
        token: githubToken, path: `repos/${publishRepos[0]}/issues?state=all&per_page=100`,
      }, []);
      if (cancelled) return;
      // Count only planner-published issues — those with a ref marker (a recovered ref isn't "#<n>").
      setRecoverable(recoverIssues(rows ?? [], publishRepos[0]).filter((i) => !i.ref.startsWith("#")).length);
    })();
    return () => { cancelled = true; };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [visible, githubToken, publishRepos.join(","), effectiveProjectId]);

  return { handlePublish, launchTriage, handleRecover, triaging, triageError, triageNote, recoverable, recovering, publishPhase, setPublishPhase, ghStatus, quarantineDialog };
}

// usePlanSkillsManagement (#1474) — the planner's session skill-group + live skills refresh,
// extracted verbatim from Planning.tsx. Side-effect only (no state, no return).

import { useEffect } from "react";
import { useAppStore } from "@/store";
import { usePoll } from "@/shared/hooks/usePoll";

export function usePlanSkillsManagement(sessionGroupId: string, projectTitle: string): void {
  const ensureSessionGroup = useAppStore(s => s.ensureSessionGroup);
  const refreshSkills = useAppStore(s => s.refreshSkills);
  // Whether the per-project session group exists YET. It's created lazily by
  // `bsc-skill add --group "$BSC_SESSION_SKILL_GROUP"` the first time the planner authors a skill —
  // NOT on planner open, so a project that authors none never leaves an empty group behind (#1616).
  const groupExists = useAppStore(s => s.skillGroups.some(g => g.id === sessionGroupId));

  // Adopt the session group ONCE IT EXISTS (#1419/#1616): never pre-create it. When the planner authors
  // its first skill, bsc-skill creates the group (placeholder name = its id); the refresh poll below
  // surfaces it here, and we rename the placeholder to the project name — and again if the title later
  // changes — without clobbering members. Persistent: reopening the planner keeps collecting into it.
  useEffect(() => {
    if (groupExists && sessionGroupId && projectTitle) ensureSessionGroup(sessionGroupId, projectTitle);
  }, [groupExists, sessionGroupId, projectTitle, ensureSessionGroup]);

  // Re-read the global skills.db while planning so skills the planner authors with `bsc-skill add`
  // (and their session-group membership) surface live in the pane — the skills.json file-poll that
  // used to do this was retired (#1417/#1419). Cheap (no push-back); 2.5s ≈ the section-poll cadence.
  usePoll(() => { void refreshSkills(); }, 2500, [refreshSkills]);
}

// usePlannerBlueprint (#1474) — the planner's blueprint lifecycle derivation (orientation),
// extracted verbatim from Planning.tsx.

import { useMemo } from "react";
import { type Blueprint } from "@/features/planner/stages/blueprints";
import { plannerTreatAsExisting } from "@/features/planner/session/plannerIntro";

interface BlueprintDeps {
  blueprints: Blueprint[];
  effectiveBlueprintId: string;
  /** Whether the project is published (activeProjectId set) — the save-state proxy. */
  isExisting: boolean;
}

export interface PlannerBlueprint {
  activeBlueprint: Blueprint | undefined;
  treatAsExisting: boolean;
}

export function usePlannerBlueprint(deps: BlueprintDeps): PlannerBlueprint {
  const { blueprints, effectiveBlueprintId, isExisting } = deps;

  const activeBlueprint = useMemo(() => blueprints.find(b => b.id === effectiveBlueprintId), [blueprints, effectiveBlueprintId]);
  // #1286: the planner's orientation (its intro greeting AND its generated CLAUDE.md spec) follows
  // the blueprint's lifecycle MODE — an operate-mode blueprint (transform/harden/maintain) takes the
  // "existing repos" orientation even on a fresh draft, where the bare `isExisting` (saved-project)
  // proxy would mis-greet it as a new greenfield project. Plain `isExisting` stays for the
  // drafting/expanding UI labels (genuinely about save-state).
  const treatAsExisting = plannerTreatAsExisting({ isSaved: isExisting, mode: activeBlueprint?.mode });

  return { activeBlueprint, treatAsExisting };
}

// usePlannerRepoManagement (#1474) — the planner's headless repo auto-clone, extracted verbatim
// from Planning.tsx. Eagerly clones each linked repo into the project dir as it appears, persisting
// the link in plan.db. The linked set is DB-owned: the planner runs `bsc plan repo add owner/repo`,
// the section poll reflects `plan_list_repos` into `effectiveRepos`, and this effect clones each new
// entry. Side-effect only — returns nothing.

import { useEffect, useRef } from "react";
import { invoke } from "@tauri-apps/api/core";
import { bscRun } from "@/shared/lib/core/bsc";
import { useAppStore } from "@/store";

export function usePlannerRepoManagement(effectiveProjectId: string, effectiveRepos: string[]): void {
  // Eager auto-clone (#508): the visible repo strip was removed from the header, but its clone
  // engine lives on headlessly here. Each linked repo (surfaced via the plan.db poll) is cloned
  // into the project dir as soon as it appears, populating projectLocalRepos → linkedRepos →
  // setup_workspaces, so the planner can read repo contents during planning (triage launch
  // re-clones fail-soft, but that's too late for in-session context). Idempotent on the Rust side.
  const autoCloneRef = useRef<Set<string>>(new Set());
  useEffect(() => {
    if (!effectiveProjectId) return;
    const cloned = new Set(useAppStore.getState().projectLocalRepos[effectiveProjectId] ?? []);
    for (const fullName of effectiveRepos) {
      if (cloned.has(fullName) || autoCloneRef.current.has(fullName)) continue;
      autoCloneRef.current.add(fullName);
      invoke<string>("clone_repo", { project: effectiveProjectId, fullName })
        .then(() => {
          useAppStore.getState().addProjectRepo(effectiveProjectId, fullName);
          // Persist the link in the hub's plan.db (#1012) — durable across a store/app-state reset,
          // which the store-only persistence didn't survive.
          void bscRun(effectiveProjectId, ["plan", "repo", "add", fullName]);
        })
        .catch(e => console.error(`clone ${fullName} failed:`, e))
        .finally(() => autoCloneRef.current.delete(fullName));
    }
  }, [effectiveProjectId, effectiveRepos]);
}

// usePlannerTagStream (#1474) — the planner's PTY output buffer. Owns the two output buffers and a
// `processChunk` that, per PTY data chunk, strips ANSI, accumulates, and caps the buffer. The
// planner used to emit structured `<tag>`s parsed here; every one has since moved to plan.db via a
// `bsc plan …` command reflected by the section poll (the last, `<plan_focus>`, removed in #2017),
// so this hook no longer parses anything — it just maintains the buffers the autopilot reads.
//
//   bufRef         — the accumulated output buffer (the caller's restart clears it)
//   autopilotTxRef — an UN-consumed copy of the same output, read by the autopilot idle-detector
//
// Both refs are returned so the caller's restart (clears bufRef) and autopilot (reads
// autopilotTxRef) keep their existing access. `processChunk` is a stable callback, so the
// once-attached `pty_data` listener is set up a single time.

import { useCallback, useRef } from "react";
import { stripAnsi } from "@/features/planner/session/planningTerminal";

export interface PlannerTagStream {
  /** Feed one PTY data chunk: accumulate it and parse/dispatch any structured tags it completes. */
  processChunk: (payload: string) => void;
  /** The tag-scan buffer (the caller's restart clears it). */
  bufRef: React.MutableRefObject<string>;
  /** The un-consumed output copy the autopilot idle-detector reads. */
  autopilotTxRef: React.MutableRefObject<string>;
}

export function usePlannerTagStream(): PlannerTagStream {
  // Accumulated stripped output. Historically drained by the tag parsers as they consumed tags;
  // every planner tag now writes to plan.db via `bsc plan …` and is reflected by the section poll,
  // so nothing is parsed here anymore (the last, `<plan_focus>`, was removed in #2017). The buffer +
  // its un-consumed autopilot copy remain: the autopilot idle-detector (#746) reads them, and the
  // cap keeps them bounded.
  const bufRef = useRef("");
  // Autopilot (#746): an un-consumed copy of the planner's raw output, for idle-detection + user-sim.
  const autopilotTxRef = useRef("");

  const processChunk = useCallback((payload: string) => {
    bufRef.current += stripAnsi(payload);
    autopilotTxRef.current += stripAnsi(payload); // un-consumed copy for the autopilot (#746)

    // Cap buffer to prevent unbounded growth while preserving any partial
    // in-progress tag that hasn't received its closing counterpart yet.
    const MAX_BUF = 120_000;
    if (bufRef.current.length > MAX_BUF) {
      const lastTagStart = bufRef.current.lastIndexOf("<");
      bufRef.current = bufRef.current.slice(
        lastTagStart > 0 && lastTagStart > bufRef.current.length - MAX_BUF
          ? lastTagStart
          : bufRef.current.length - MAX_BUF
      );
    }
  }, []);

  return { processChunk, bufRef, autopilotTxRef };
}

// usePlannerTerminal (#1775, extracted from Planning.tsx) — owns the planner's xterm.js terminal
// and its PTY lifecycle:
//   • mount — create the terminal + fit addon, subscribe to pty_data/pty_exit, run setup_workspaces
//     (the isolated planning dir + CLAUDE.md), write the plan-only role gate into session settings,
//     and spawn `claude` with the fresh-only intro prompt. pty_kill on unmount ends it cleanly.
//   • re-fit — re-measure when the panel becomes visible (hidden → shown), after a short delay, and
//     once the mono font loads (cell metrics are wrong until then).
//   • re-sync — re-run setup_workspaces when a linked repo resolves after the initial mount.
// This is a behavior-preserving move out of the component; the once-effect deps (and the two
// eslint-disables they require) are reproduced exactly — NO logic change.
import { useEffect, type RefObject, type MutableRefObject } from "react";
import type { Terminal } from "@xterm/xterm";
import { invoke } from "@tauri-apps/api/core";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { useAppStore } from "@/store";
import { roleCapability, roleDeniedCommands, roleWriteRules } from "@/shared/lib/session/sessionRoles";
import { useScreenSession } from "@/shared/lib/session/useScreenSession";
import { TURN_ACCOUNTING_HOOKS } from "@/shared/lib/session/turnHooks";
import { resolveAllInstalledMcp, toSessionPayloads, mcpAllowRules } from "@/features/mcp";
import { plannerIntroMode, composePlannerIntro } from "@/features/planner/session/plannerIntro";
import { plannerLaunchConfig } from "@/features/planner/session/plannerLaunch";
import { resolvePlannerSandbox } from "@/features/planner/session/plannerSandbox";
import { TERM_THEME } from "@/app/console/lib/terminalConstants";
import type { Command, Schedule } from "@/shared/data/mock";

export interface PlannerTerminalOpts {
  paneId: string;
  /** Whether the planning panel is on-screen — drives the re-fit effect. */
  visible: boolean;
  effectiveProjectId: string;
  /** full_names linked + cloned for this project; drives the post-mount workspace re-sync. */
  linkedRepos: string[];
  treatAsExisting: boolean;
  activeProjectName: string;
  activeProjectNumber: number;
  planningPitch: string;
  /** The blueprint's enabled stage ids for a project key — scopes the planner CLAUDE.md (#A). */
  stageIdsFor: (key: string) => string[];
  /** Re-read the setup baseline after a workspace setup (#756). */
  refreshSetupSig: () => void;
  /** Parse structured <tag>s out of the stripped PTY output stream (#1474, usePlannerTagStream). */
  processChunk: (chunk: string) => void;
  commands: Command[];
  schedules: Schedule[];
  /** Write the resolved planner hub dir up to the owning component (read by the MCP + tunnel wiring,
   *  so the state cell lives in Planning where those earlier hooks can see it) (#801). */
  setPlanningDir: (dir: string) => void;
}

export interface PlannerTerminalHandle {
  /** Host element for the xterm canvas — attach to the terminal container div. */
  containerRef: RefObject<HTMLDivElement | null>;
  /** The live xterm instance (null before mount / after unmount) — read by sendPrompt + restart. */
  termRef: MutableRefObject<Terminal | null>;
}

export function usePlannerTerminal(opts: PlannerTerminalOpts): PlannerTerminalHandle {
  const {
    paneId, visible, effectiveProjectId, linkedRepos, treatAsExisting,
    activeProjectName, activeProjectNumber, planningPitch, stageIdsFor, refreshSetupSig,
    processChunk, commands, schedules, setPlanningDir,
  } = opts;

  // The whole xterm + PTY lifecycle (terminal literal, subscribe-before-create ordering,
  // ResizeObserver, refit, cleanup) lives in the shared hook; this wrapper owns only the PLANNER
  // launch path (workspace setup → role gate + MCP → intro → sandbox → pty_create), the tag-parse
  // onData hook, and the repo-resync effect below. pty_kill is called on unmount so navigating away
  // ends the session cleanly. The once-effect launch is a behavior-preserving move — NO logic change.
  const { containerRef, termRef } = useScreenSession({
    paneId,
    termTheme: TERM_THEME,
    visible,
    exitBanner: "\r\n\x1b[33m[session ended — navigate away and back to restart]\x1b[0m\r\n",

    // Parse structured tags out of the stripped output stream (#1474, usePlannerTagStream).
    onData: (payload) => processChunk(payload),

    // Capture state at mount time (synchronously, before the RAF) for workspace sync.
    snapshot: () => ({
      repoSnapshot:        linkedRepos, // string[] of full_names
      treatAsExistingSnap: treatAsExisting,
      projNameSnap:        activeProjectName,
      projNumberSnap:      activeProjectNumber,
      pitchSnap:           planningPitch,
      projIdSnap:          effectiveProjectId,
      ghLoginSnap:         useAppStore.getState().githubUser?.login ?? "",
      ghNameSnap:          useAppStore.getState().githubUser?.name  ?? "",
      automationsSnap: [
        ...commands.map(c => ({ id: c.id, name: c.name, command: c.cmd, schedule: null })),
        ...schedules.map(sc => ({ id: sc.id, name: sc.name, command: sc.detail, schedule: sc.when })),
      ],
    }),

    launch: async (term, snap) => {
      const {
        repoSnapshot, treatAsExistingSnap, projNameSnap, projNumberSnap,
        pitchSnap, projIdSnap, ghLoginSnap, ghNameSnap, automationsSnap,
      } = snap;

      // Create the isolated planning workspace directory with settings.json + CLAUDE.md.
      const paths = await safeInvoke<{ planning_dir: string } | null>(
        "setup_workspaces",
        {
          repoFullNames: repoSnapshot,
          automations:   automationsSnap,
          isExisting:    treatAsExistingSnap,
          projectName:   projNameSnap,
          projectNumber: projNumberSnap,
          pitch:         pitchSnap,
          projectKey:    projIdSnap,
          githubLogin:   ghLoginSnap,
          githubName:    ghNameSnap,
          enabledStages: stageIdsFor(projIdSnap), // scope the planner CLAUDE.md to the blueprint (#A)
        },
        null,
        (e: unknown) => console.error("workspace setup failed:", e),
      );
      refreshSetupSig(); // baseline updated (#756)
      if (paths) setPlanningDir(paths.planning_dir); // for the relay planner-pane mirror (#801)

      // Launch claude inside the isolated planning directory.
      // Inject the stored GitHub token so `gh` CLI and direct API calls work
      // without requiring the user to separately authenticate the gh CLI.
      const token = useAppStore.getState().githubToken;
      const ghEnv: Record<string, string> = token ? { GH_TOKEN: token, GITHUB_TOKEN: token } : {};
      // Role gate (#219): the planning session launches as the DIRECTOR — planning and directing
      // are one actor at two phases of a project, so the capability moved onto that role rather than
      // being duplicated. It stays plan-only: git/gh read, writes scoped to the plan files, so it can
      // read for context but neither edit project code nor mutate the repo/GitHub (publishing is an
      // explicit, separately-gated step).
      const planCap = roleCapability("director");
      const planWrite = roleWriteRules(planCap);
      // Expose EVERY installed MCP server to the planner (#1054), project scope ignored: the planner
      // is the assignment hub, so it sees all downloaded servers — it can call them while planning
      // (e.g. research sources for a skill) and assign them to the workers that need them.
      const plannerMcp = toSessionPayloads(resolveAllInstalledMcp(useAppStore.getState().mcpServers), []).mcp;
      // The role gate covers the planner's scoped plan-file writes + git/gh read-only.
      // WebFetch (docs / version / pricing lookups) and Read are added explicitly here so
      // this single role-launch path fully sources the planner's tools — replacing the
      // hardcoded settings.json literal that setup_workspaces used to write (#799).
      await safeInvoke("ensure_session_settings", {
        cwd:             paths?.planning_dir ?? "",
        allowedCommands: [],
        deniedCommands:  roleDeniedCommands(planCap),
        mcpServers:      plannerMcp,
        // Turn accounting (#3455): the planner's bespoke launch must ALSO register the observability
        // floor. bsc-tokens is the only per-session token source, so without it the planner's (often
        // large) planning cost is invisible to `bsc metrics`. Shared with the generic path.
        hooks:           TURN_ACCOUNTING_HOOKS,
        // Auto-approve every MCP server the planner sees (Research/Compliance + any downloaded one)
        // so it can call them while planning — e.g. the Research MCP when grounding a skill — without
        // a per-tool permission prompt. `enabledMcpjsonServers` only trusts the server to LOAD.
        allowToolRules:  [...planWrite.allow, "Read", "WebFetch", ...mcpAllowRules(plannerMcp)],
        denyToolRules:   planWrite.deny,
        replacePermissions: true,
      }, undefined, (e: unknown) => console.error("planner session settings failed:", e));
      // Planner introduction (#1240): a user-facing kickoff that has the planner OPEN the
      // conversation (introduce itself, sketch the stage journey, summarize capabilities, ask one
      // orienting question) instead of launching into a quiet terminal. Baked into the claude launch
      // arg as a FRESH-ONLY startup prompt — the backend (which knows the conversation history)
      // delivers it only on a genuinely new session and drops it on `--continue` resume, so a
      // returning user isn't re-greeted. For a new project the user's pitch rides along so the
      // planner acknowledges it rather than asking what they're building (replaces the old
      // idle-detection pitch-typing). On failure it's undefined → the launch falls back to initCmd.
      const introMode = plannerIntroMode({ isExisting: treatAsExistingSnap });
      const introText = await safeInvoke<string>("planner_intro_prompt", { mode: introMode }, "",
        (e: unknown) => console.error("planner intro prompt failed:", e));
      // Run the planner on the selected harness: Claude Code, or bsc-agent (any LLM) when chosen or
      // forced by a local/ollama provider Claude can't drive (#1078). bsc-agent gets the same plan-only
      // role gate, MCP, and provider/model/base-url via BSC_AGENT_* env; context + the intro prompt +
      // plan state come through identically.
      const launch = plannerLaunchConfig(useAppStore.getState(), ghEnv);
      // bsc-agent is a one-shot loop, so it never receives stage 1's directive via runtime injection
      // (Claude does). Bake the first active stage's directive into the intro so a weak local model
      // begins discovery instead of greeting and then waiting to be advanced (#qwen).
      let firstStageDirective: string | undefined;
      if (launch.providerId === "bsc-agent") {
        const firstStage = stageIdsFor(projIdSnap)[0];
        if (firstStage) {
          firstStageDirective = await safeInvoke<string>(
            "planner_stage_directive", { id: firstStage }, "",
            (e: unknown) => console.error("planner stage directive failed:", e),
          ) || undefined;
        }
      }
      const startupPrompt = composePlannerIntro(introText, introMode, pitchSnap ?? "", firstStageDirective) || undefined;
      // #1988: opt-in (off by default) — relocate the hub into the sealed WSL2 distro + spawn INSIDE
      // it when the sandbox toggle is on AND the planner runs on bsc-agent (shared with the restart
      // path so they can't drift; host fallback on failure). Toggling restarts the planner to convert.
      const sandbox = await resolvePlannerSandbox(launch.providerId, paths?.planning_dir ?? "", projIdSnap);
      await safeInvoke("pty_create", {
        paneId:  paneId,
        cols:    term.cols,
        rows:    term.rows,
        cwd:     sandbox.cwd,
        initCmd: launch.initCmd,
        startupPrompt,
        startupPromptFreshOnly: launch.startupPromptFreshOnly,
        continueSession: launch.continueSession,
        env:     launch.env,
        providerId: launch.providerId,
        wslDistro: sandbox.wslDistro,
      }, undefined, console.error);
    },
  });

  // Re-sync CLAUDE.md whenever a repo resolves after the initial mount.
  useEffect(() => {
    if (linkedRepos.length === 0) return;
    const { commands: cmds, schedules: scheds } = useAppStore.getState();
    invoke("setup_workspaces", {
      repoFullNames: linkedRepos,
      automations: [
        ...cmds.map(c => ({ id: c.id, name: c.name, command: c.cmd, schedule: null })),
        ...scheds.map(sc => ({ id: sc.id, name: sc.name, command: sc.detail, schedule: sc.when })),
      ],
      isExisting:    treatAsExisting,
      projectName:   activeProjectName,
      projectNumber: activeProjectNumber,
      pitch:         planningPitch,
      projectKey:    effectiveProjectId,
      githubLogin:   useAppStore.getState().githubUser?.login ?? "",
      githubName:    useAppStore.getState().githubUser?.name  ?? "",
      enabledStages: stageIdsFor(effectiveProjectId), // scope the planner CLAUDE.md (#A)
    }).then(() => refreshSetupSig()).catch(console.error); // baseline updated (#756)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [linkedRepos]);

  return { containerRef, termRef };
}

// usePlanningTitle (#1775, extracted from Planning.tsx) — the editable project title for both
// lifecycles, KEEPING the frozen session key (#2409: renames are display-only — the folder keeps
// its birth-slug; a later reopen under the new name resolves via the reopen-mismatch modal):
//   • PUBLISHED rename (#1226) — commit updates the GitHub Project board title + local name.
//   • UNPUBLISHED draft (#1222) — commit persists to the draft record keyed by the frozen key.
import { useState, useCallback } from "react";
import { useAppStore } from "@/store";
import { fireInvoke } from "@/shared/lib/core/safeInvoke";
import { githubGraphql } from "@/shared/lib/github/github";
import { planRename, applyRename } from "@/features/planner/session/renameProject";
import { planDraftCommit } from "@/features/planner/session/draftTitle";

type Store = ReturnType<typeof useAppStore.getState>;

export function usePlanningTitle(opts: {
  activeProjectId: Store["activeProjectId"];
  activeProjectName: Store["activeProjectName"];
  activeProjectNumber: Store["activeProjectNumber"];
  activeProjectRepos: Store["activeProjectRepos"];
  planningTitle: Store["planningTitle"];
  setPlanningTitle: Store["setPlanningTitle"];
  effectiveProjectId: string;
}) {
  const {
    activeProjectId, activeProjectName, activeProjectNumber, activeProjectRepos,
    planningTitle, setPlanningTitle, effectiveProjectId,
  } = opts;

  // ── Rename a PUBLISHED project (#1226) ──────────────────────────────────────────
  const [titleEdit, setTitleEdit] = useState<string | null>(null);
  const [renameErr, setRenameErr] = useState<string | null>(null);
  const commitRename = useCallback(async () => {
    // The duplicate guard compares against OTHER projects' frozen keys — the draft-map keys
    // (name-derived slugs, #2409). Renames are display-only (the folder keeps its birth-slug), so
    // a rename that slugs onto another key would only surface later as a reopen collision — this
    // guard catches it up front where the store knows the other keys.
    const st0 = useAppStore.getState();
    const otherKeys = new Set(
      Object.keys(st0.localDraftProjects).filter((k) => k !== effectiveProjectId),
    );
    const plan = planRename(titleEdit ?? "", activeProjectName, activeProjectId, otherKeys);
    setTitleEdit(null);
    if (plan.kind === "noop") { setRenameErr(null); return; }
    if (plan.kind === "error") { setRenameErr(plan.message); return; }
    const st = useAppStore.getState();
    setRenameErr(
      await applyRename(activeProjectId!, plan.title, {
        graphql: githubGraphql,
        setMeta: st.setActiveProjectMeta,
        repo: st.activeProjectRepo,
        number: activeProjectNumber,
        repos: activeProjectRepos,
      }),
    );
    // Keep the on-disk hub title (`projects/<key>/.title`) in step with the rename so the durable
    // name — read by list_local_projects and the session skill-group naming — reflects the new title.
    fireInvoke("set_project_title", { projectKey: effectiveProjectId, title: plan.title });
  }, [titleEdit, activeProjectName, activeProjectId, activeProjectNumber, activeProjectRepos, effectiveProjectId]);

  // ── Persist a DRAFT title edit (#1222) ──────────────────────────────────────────
  const [draftTitleErr, setDraftTitleErr] = useState<string | null>(null);
  const commitDraftTitle = useCallback(() => {
    const st = useAppStore.getState();
    const draft = st.localDraftProjects[effectiveProjectId];
    if (!draft) { setDraftTitleErr(null); return; } // not an unpublished draft — nothing to persist
    const otherKeys = new Set<string>();
    for (const k of Object.keys(st.localDraftProjects)) if (k !== effectiveProjectId) otherKeys.add(k);
    const plan = planDraftCommit(planningTitle, draft.title, otherKeys);
    if (plan.kind === "revert") { setPlanningTitle(draft.title); setDraftTitleErr(null); return; }
    if (plan.kind === "noop") { setDraftTitleErr(null); return; }
    if (plan.kind === "error") { setDraftTitleErr(plan.message); return; } // keep the typed value to fix
    st.updateDraftProject(effectiveProjectId, { title: plan.title });
    // Mirror the draft rename into the durable hub title (`.title`) so the on-disk name doesn't fall
    // back to a key-derived placeholder once goal.md/the store drift out of view.
    fireInvoke("set_project_title", { projectKey: effectiveProjectId, title: plan.title });
    setDraftTitleErr(null);
  }, [planningTitle, effectiveProjectId, setPlanningTitle]);

  return { titleEdit, setTitleEdit, renameErr, setRenameErr, commitRename, draftTitleErr, setDraftTitleErr, commitDraftTitle };
}

// Fetch orchestration for the live Repo Pulse page (#413). Pulls the GitHub data
// the Pulse panels need through the ETag-cached backend (lib/github), then runs
// the pure mappers in lib/repoPulseLive to assemble a view model. Side-effectful;
// the mapping logic it calls is unit-tested separately.
//
// Cheap+exact panels (velocity, CI, review latency, branches) use list endpoints.
// Diff-derived panels (lines/day, churn-by-area, hottest files, contributor
// ±lines) need per-commit detail calls — capped to the most recent N commits.
import { useState, useEffect } from "react";
import { githubRequest, isGithubAuthError } from "@/shared/lib/github/github";
import type { GithubRepo } from "@/store";
import {
  mapVelocity, mapChurnAreas, mapHottestFiles, mapContributors, mapCI,
  mapReviewLatency, mapBranches, deriveKpis,
  type GhCommitItem, type GhCommitDetail, type GhPull, type GhBranchItem,
  type GhWorkflowItem, type GhRun, type GhCompare, type CiHealth, type PulseKpis,
} from "@/shared/lib/github/repoPulseLive";
import type {
  VelocitySlice, ChurnArea, ChurnFile, Contributor, Workflow, Branch,
} from "@/shared/data/repoPulse";

/** How many recent commits to fetch full diffs for (the diff-derived panels). */
const DETAIL_CAP = 40;
/** How many branches to run a compare (ahead/behind) call for. */
const COMPARE_CAP = 8;
const WINDOW_DAYS = 14;

export interface RepoPulseLive {
  repo: { name: string; branch: string; desc: string; lang: string; pushedMin: number };
  velocity: VelocitySlice;
  churnAreas: ChurnArea[];
  hottestFiles: ChurnFile[];
  contributors: Contributor[];
  ci: CiHealth;
  workflows: Workflow[];
  branches: Branch[];
  reviewBuckets: Array<{ label: string; v: number }>;
  kpis: PulseKpis;
  /** True while diff-derived panels reflect only the most recent DETAIL_CAP commits. */
  partialDiffs: boolean;
}

export interface UseRepoPulse {
  data: RepoPulseLive | null;
  loading: boolean;
  error: string | null;
}

function minutesSince(iso: string): number {
  return Math.max(0, Math.round((Date.now() - new Date(iso).getTime()) / 60000));
}

export function useRepoPulse(repo: GithubRepo | null): UseRepoPulse {
  const [data, setData] = useState<RepoPulseLive | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const slug = repo?.full_name ?? "";

  useEffect(() => {
    if (!repo || !slug) { setData(null); setError(null); return; }
    let cancelled = false;
    setLoading(true);
    setError(null);

    (async () => {
      try {
        const since = new Date(Date.now() - WINDOW_DAYS * 86_400_000).toISOString();
        const get = <T,>(path: string, fallback: T): Promise<T> =>
          githubRequest<T>(path).catch((e) => { if (isGithubAuthError(e)) throw e; return fallback; });

        const [commits, pulls, branches, wfResp, runResp] = await Promise.all([
          get<GhCommitItem[]>(`repos/${slug}/commits?per_page=100&since=${since}`, []),
          get<GhPull[]>(`repos/${slug}/pulls?state=all&per_page=100&sort=created&direction=desc`, []),
          get<GhBranchItem[]>(`repos/${slug}/branches?per_page=100`, []),
          get<{ workflows: GhWorkflowItem[] }>(`repos/${slug}/actions/workflows`, { workflows: [] }),
          get<{ workflow_runs: GhRun[] }>(`repos/${slug}/actions/runs?per_page=100`, { workflow_runs: [] }),
        ]);
        if (cancelled) return;

        // Per-commit diffs for the most recent N commits (bounded, cached).
        const detailShas = commits.slice(0, DETAIL_CAP).map(c => c.sha);
        const details = (await Promise.all(
          detailShas.map(sha => get<GhCommitDetail | null>(`repos/${slug}/commits/${sha}`, null)),
        )).filter((d): d is GhCommitDetail => !!d);
        if (cancelled) return;

        // ahead/behind for the default branch vs a capped set of other branches.
        const defaultBranch = repo.default_branch;
        const compareTargets = branches
          .filter(b => b.name !== defaultBranch)
          .slice(0, COMPARE_CAP);
        const compareResults = await Promise.all(
          compareTargets.map(b =>
            get<GhCompare>(`repos/${slug}/compare/${defaultBranch}...${b.name}`, { ahead_by: 0, behind_by: 0 })
              .then(r => [b.name, r] as const)),
        );
        if (cancelled) return;
        const compares = Object.fromEntries(compareResults);

        const now = new Date();
        const velocity = mapVelocity(commits, pulls, details, WINDOW_DAYS, now);
        const { ci, workflows } = mapCI(runResp.workflow_runs, wfResp.workflows);
        const contributors = mapContributors(commits, details);

        const live: RepoPulseLive = {
          repo: {
            name: repo.full_name,
            branch: defaultBranch,
            desc: repo.description ?? "",
            lang: repo.language ? repo.language.toLowerCase() : "—",
            pushedMin: minutesSince(repo.pushed_at),
          },
          velocity,
          churnAreas: mapChurnAreas(details),
          hottestFiles: mapHottestFiles(details),
          contributors,
          ci,
          workflows,
          branches: mapBranches(branches, pulls, compares, defaultBranch),
          reviewBuckets: mapReviewLatency(pulls),
          kpis: deriveKpis(velocity, ci, pulls, contributors, now),
          partialDiffs: commits.length > DETAIL_CAP,
        };
        if (!cancelled) { setData(live); setLoading(false); }
      } catch (e) {
        if (cancelled) return;
        setError(isGithubAuthError(e) ? "GitHub authorization failed — reconnect in Settings." : "Couldn't load repo data from GitHub.");
        setLoading(false);
      }
    })();

    return () => { cancelled = true; };
  }, [repo, slug]);

  return { data, loading, error };
}

// useSetupSignature (#1775, extracted from Planning.tsx) — the "context updated · refresh" badge
// signal (#175/#756). `currentSig` is the live signature of the inputs (computed in Rust so its
// format can't drift from the baseline); `lastSetupSig` is the baseline setup_workspaces last wrote.
// When they diverge (a repo linked / blueprint changed mid-session, or the planner template bumped)
// `contextStale` is true. `refreshSetupSig` re-reads the baseline — call after every workspace setup.
import { useState, useEffect, useCallback } from "react";
import { invoke } from "@tauri-apps/api/core";

export function useSetupSignature(
  effectiveProjectId: string,
  linkedRepos: string[],
  stageIdsFor: (key: string) => string[],
): { currentSig: string | null; lastSetupSig: string | null; refreshSetupSig: () => void; contextStale: boolean } {
  const [currentSig, setCurrentSig] = useState<string | null>(null);
  const [lastSetupSig, setLastSetupSig] = useState<string | null>(null);
  useEffect(() => {
    let live = true;
    invoke<string>("compute_context_signature", {
      repoFullNames: linkedRepos,
      enabledStages: stageIdsFor(effectiveProjectId),
    }).then(sig => { if (live) setCurrentSig(sig); }).catch(() => { if (live) setCurrentSig(null); });
    return () => { live = false; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [linkedRepos, effectiveProjectId]);
  // Re-read the baseline the backend last wrote — called on open and after every workspace setup
  // (mount / link / restart), so the badge reflects the most recent regeneration.
  const refreshSetupSig = useCallback(() => {
    invoke<string>("get_context_signature", { projectKey: effectiveProjectId })
      .then(s => setLastSetupSig(s || null)).catch(() => {});
  }, [effectiveProjectId]);
  useEffect(() => { refreshSetupSig(); }, [refreshSetupSig]);
  const contextStale = !!currentSig && !!lastSetupSig && currentSig !== lastSetupSig;
  return { currentSig, lastSetupSig, refreshSetupSig, contextStale };
}

/**
 * Bucket K timestamp streams into per-day counts over a rolling N-day window, aligned to one label
 * axis — the shape every "activity over the last N days" chart needs.
 *
 * Two properties are the whole point, and both are easy to get wrong by hand:
 *
 * 1. **Empty days are present.** The window is built first and every stream is tallied INTO it, so a
 *    day with no events is a `0`, not a missing entry. Deriving labels from the data instead (the
 *    obvious shortcut) silently compresses quiet days out of the axis, which makes a gap look like a
 *    dip and misstates the trend.
 * 2. **The series are aligned.** Every returned series has exactly `days` entries in the same order as
 *    `labels`, so index `i` means the same day in all of them. A chart layering two series cannot check
 *    this and will happily plot them against each other misaligned.
 *
 * Days are UTC — a rolling window whose bucket boundaries move with the viewer's timezone would make
 * the same data tell two stories. Timestamps are ISO-8601; anything unparseable or outside the window
 * is dropped rather than clamped, because a bad timestamp landing on an edge day is a fabricated event.
 *
 * Harvested from the Fleet page's throughput panel (#3462/#3465).
 */

/** The day axis: display labels and the `YYYY-MM-DD` keys they bucket by, oldest → newest. */
export interface DayWindow {
  labels: string[];
  keys: string[];
}

/** The aligned result: one label axis and one equal-length numeric series per input stream. */
export interface WindowedTally<TName extends string> {
  labels: string[];
  series: Record<TName, number[]>;
}

/**
 * The last `days` UTC days ending at `now` (inclusive), oldest first.
 *
 * `days <= 0` yields an empty window rather than throwing — a caller asking for no window gets no
 * window, and every tally over it is correctly empty.
 */
export function dayWindow(days: number, now: Date): DayWindow {
  const labels: string[] = [];
  const keys: string[] = [];
  for (let i = Math.max(0, Math.floor(days)) - 1; i >= 0; i--) {
    const d = new Date(now.getTime() - i * 86_400_000);
    labels.push(`${d.getUTCMonth() + 1}/${d.getUTCDate()}`);
    keys.push(d.toISOString().slice(0, 10));
  }
  return { labels, keys };
}

/**
 * Count the timestamps falling on each day of `win`, in window order.
 *
 * Null/undefined/unparseable entries are skipped — these streams come from APIs where "not merged
 * yet" is a null timestamp, so filtering at the call site would be required of every caller.
 */
export function tallyByDay(win: DayWindow, timestamps: ReadonlyArray<string | null | undefined>): number[] {
  const index = new Map(win.keys.map((k, i) => [k, i]));
  const out = new Array<number>(win.keys.length).fill(0);
  for (const ts of timestamps) {
    if (!ts) continue;
    const at = index.get(ts.slice(0, 10));
    if (at !== undefined) out[at] += 1;
  }
  return out;
}

/**
 * Tally several named streams over ONE window, so the result is aligned by construction.
 *
 * Preferred over calling {@link tallyByDay} per stream: sharing the window is what guarantees the
 * series line up, and doing it here removes the caller's opportunity to build two windows a
 * millisecond apart and land the boundary event in different buckets.
 */
export function windowedTally<TName extends string>(
  streams: Record<TName, ReadonlyArray<string | null | undefined>>,
  days: number,
  now: Date,
): WindowedTally<TName> {
  const win = dayWindow(days, now);
  const series = {} as Record<TName, number[]>;
  for (const name of Object.keys(streams) as TName[]) {
    series[name] = tallyByDay(win, streams[name]);
  }
  return { labels: win.labels, series };
}
